// Üretilen dosya: tool/ozgun/uret.py. Fizik ve Astronomi · Basit harmonik hareket, evrensel kütleçekim, Kepler yasaları ve uydu yörüngeleri (yay-sarkaç periyodu, kaçış hızı, yer eşzamanlı yörünge) (orta).
const ozPhysics16Orta = <(String, String, List<String>, String)>[
  ('Yatay düzlemde -A ve +A genlik sınırları arasında salınan bir blok, denge noktasından +A ucuna doğru ilerlerken hız, ivme ve uzanım vektörlerinden hangilerinin yönü pozitif (+x) tarafı gösterir?', 'Uzanım ve hız vektörleri pozitif yönlüdür, ivme negatiftir', ['Üç vektörün tamamı pozitif x yönünü işaret eder', 'Yalnızca ivme vektörü pozitif, diğer ikisi negatif yönlüdür', 'Hız ve ivme pozitif yönlü iken uzanım negatif taraftadır'], 'Cisim O\'dan +A\'ya giderken konumu +x bölgesindedir (uzanım +), hareketi +x yönündedir (hız +), ancak ivme merkeze yani O\'ya yönelik olduğundan (-x) yönlüdür.'),
  ('Periyodu 12 saniye olan basit harmonik bir osilatör, harekete denge konumundan pozitif yönde başladıktan 2 saniye sonra genliğin kaçta kaçı kadar uzanıma ulaşır?', 'Genliğin kök üç bölü ikisi kadar uzaklığa', ['Genliğin tam yarısına karşılık gelen noktaya', 'Genliğin kök iki bölü ikisi kadar mesafeye', 'Genliğin dörtte üçüne eşit olan bölmeye'], 'x(t) = A * sin(2*pi*t / T) denkleminde T = 12 s ve t = 2 s yazılırsa x = A * sin(pi/3) = A * sin(60°) = (kök3 / 2)A elde edilir.'),
  ('Kütlesi 0,5 kg olan bir oyuncak vagon, sürtünmesiz rayda x(t) = 0,4 cos(5t) metre konum denklemine göre salınmaktadır. Vagon üzerine etki eden maksimum geri çağırıcı kuvvet kaç Newton büyüklüğündedir?', 'Beş Newton şiddetinde maksimum net kuvvet', ['İki buçuk Newton büyüklüğünde tepe kuvveti', 'On Newton değerinde geri çekme kuvveti', 'Bir Newton düzeyinde merkezcil zorlama kuvveti'], 'Denklemden A = 0,4 m ve omega = 5 rad/s okunur. F_max = m * omega^2 * A = 0,5 * 25 * 0,4 = 5 N olarak hesaplanır.'),
  ('Bir sismograf iğnesi deprem sarsıntısı sırasında 10 cm genlikli ve 0,5 saniye periyotlu harmonik titreşim kaydediyor. İğnenin denge çizgisinden geçerken ulaştığı en yüksek sürat kaç m/s olur (pi = 3 alınız)?', 'Bir tam onda iki metre bölü saniye', ['Sıfır tam onda altı metre bölü saniye', 'İki tam onda dört metre bölü saniye', 'Üç tam onda altı metre bölü saniye'], 'Genlik A = 0,1 m ve T = 0,5 s\'dir. Maksimum hız v_max = (2 * pi / T) * A = (2 * 3 / 0,5) * 0,1 = 12 * 0,1 = 1,2 m/s bulunur.'),
  ('Basit harmonik hareket yapan bir bilyenin uzanım-kuvvet (F-x) grafiği çizildiğinde elde edilen doğrunun özellikleri hakkında ne söylenebilir?', 'Orijinden geçen ve ikinci ile dördüncü bölgelerde uzanan negatif eğimli bir doğrudur', ['Birinci ve üçüncü bölgelerden geçen sabit pozitif eğimli bir doğrudur', 'Yatay eksene teğet duran ve yukarı doğru açılan simetrik bir paraboldür', 'Merkezi orijinde bulunan ve eksenleri genlik noktalarında kesen kapalı bir elipstir'], 'Geri çağırıcı kuvvet F = -kx bağıntısına uyar; bu nedenle grafik orijinden geçen ve eğimi -k olan negatif eğimli bir doğru parçasıdır.'),
  ('Uç noktalar olan P ve R arasında harmonik hareket yürüten bir cisim, P uç noktasından harekete başlayıp ilk kez denge noktası O\'nun tam ortasındaki M noktasına (|PM| = |MO| = A/2) 2 saniyede ulaşıyor. Bu hareketin tam periyodu kaç saniyedir?', 'On iki saniyelik tam salınım süresi', ['Sekiz saniyelik gidiş dönüş periyodu', 'Altı saniyelik harmonik tekrar zamanı', 'On altı saniyelik toplam çevrim periyodu'], 'Uç noktadan genliğin yarısına (A\'dan A/2\'ye) gelme süresi T/6\'dır (cos(wt) = 1/2 -> wt = pi/3 -> t = T/6). T/6 = 2 s ise T = 12 s olur.'),
  ('Sürtünmesiz bir olukta harmonik hareket yapan kürenin maksimum ivmesi 18 m/s^2 ve maksimum sürati 3 m/s olarak ölçülmüştür. Kürenin salınım genliği kaç santimetredir?', 'Elli santimetrelik maksimum uzanım değeri', ['Yirmi beş santimetrelik salınım genliği', 'Altı santimetrelik denge uzaklığı', 'Yüz santimetrelik yarı yörünge boyu'], 'a_max = omega^2 * A ve v_max = omega * A olduğundan oranlanırsa omega = a_max / v_max = 18 / 3 = 6 rad/s bulunur. A = v_max / omega = 3 / 6 = 0,5 m = 50 cm\'dir.'),
  ('Harmonik salınım yapan bir cismin anlık süratinin, maksimum süratinin yarısına (v_max / 2) düştüğü anda uzanım büyüklüğü genliğin kaç katıdır?', 'Karekök üç bölü iki katı uzaklıkta', ['Tam ikide biri kadar mesafede', 'Karekök iki bölü iki katı konumda', 'Dörtte üçü büyüklüğündeki bölgede'], 'v = omega * karekök(A^2 - x^2) = (omega * A) / 2 yazılıp iki tarafın karesi alınırsa A^2 - x^2 = A^2 / 4 ve buradan x = (kök3 / 2)A bulunur.'),
  ('Aynı doğrultuda ve aynı frekansla basit harmonik hareket yapan iki özdeş cisimden birincisi pozitif uç noktadayken ikincisi denge konumundan pozitif yöne doğru geçmektedir. İki salınıcı arasındaki faz farkı kaç radyandır?', 'Pi bölü iki radyanlık çeyrek periyot farkı', ['Pi radyanlık yarım periyotluk zıt faz farkı', 'Pi bölü dört radyanlık sekizde bir tur farkı', 'İki pi radyanlık tam örtüşme faz açısı'], 'Birinci cisim x1 = A sin(wt + pi/2) = A cos(wt) konumundayken ikinci cisim x2 = A sin(wt) durumundadır; aralarındaki faz farkı pi/2 radyandır.'),
  ('Dikiş makinesinin iğnesi düşey doğrultuda 2 cm strok (alt ölü nokta ile üst ölü nokta arası toplam mesafe) ile dakikada 1200 devir yapan mile bağlı olarak basit harmonik hareket yapıyor. İğnenin maksimum sürati kaç cm/s\'dir?', 'Kırk pi santimetre bölü saniye', ['Seksen pi santimetre bölü saniye', 'Yirmi pi santimetre bölü saniye', 'Yüz yirmi pi santimetre bölü saniye'], 'Toplam strok 2A = 2 cm olduğundan genlik A = 1 cm\'dir. Frekans f = 1200 / 60 = 20 Hz\'dir. v_max = 2 * pi * f * A = 2 * pi * 20 * 1 = 40 pi cm/s bulunur.'),
  ('Bir osiloskop ekranında incelenen mekanik titreşimin konum-zaman denklemi x(t) = 8 sin(pi*t / 3 + pi/6) cm olarak verilmiştir. Parçacığın t = 0 başlangıç anındaki uzanımı kaç santimetredir?', 'Dört santimetre pozitif uzanım', ['Sekiz santimetre maksimum uzanım', 'Dört kök üç santimetre ara konum', 'Sıfır santimetre denge noktası'], 't = 0 anında x(0) = 8 * sin(0 + pi/6) = 8 * sin(30°) = 8 * 0,5 = 4 cm elde edilir.'),
  ('Periyodu 2,4 saniye olan bir harmonik salınıcı, negatif uç noktadan (-A) serbest bırakıldıktan 0,9 saniye sonra hangi hareket durumundadır?', 'Denge noktasını geçmiş olup pozitif uca doğru yavaşlamaktadır', ['Negatif bölgede olup denge noktasına doğru hızlanmaktadır', 'Pozitif uç noktadan dönmüş ve dengeye doğru hızlanmaktadır', 'Tam pozitif uç noktada anlık olarak durgun haldedir'], 'T = 2,4 s için T/4 = 0,6 s ve T/2 = 1,2 s\'dir. -A\'dan başlayan cisim 0,6 s\'de O\'dan geçer, 1,2 s\'de +A\'ya varır. 0,9 s anında O ile +A arasında +A\'ya doğru yavaşlamaktadır.'),
  ('Uç noktaları K ve N olan doğrusal yörüngesi 4 eşit bölmeye (|KL| = |LM| = |MN|, M denge noktası değil; K-L-O-M-N şeklinde 4 eşit parça) ayrılmış bir harmonik harekette, cismin K\'dan L\'ye gelme süresi t1, L\'den O\'ya gelme süresi t2 ise t1/t2 oranı kaçtır?', 'İki katına eşit olan tam sayı oranı', ['Bir değerini veren eşit süre oranı', 'Karekök ikiye karşılık gelen irrasyonel oran', 'Üç katına çıkan süre karşılaştırması'], 'K(-A) ile O(0) arası iki eşit parçaya bölündüğünde L(-A/2) noktasıdır. K\'dan L\'ye geçiş süresi T/6, L\'den O\'ya geçiş süresi T/12\'dir. Oran (T/6) / (T/12) = 2 bulunur.'),
  ('Bir parçacığın ivme-uzanım denklemi SI birim sisteminde a = -36x biçiminde ölçülmüştür. Bu parçacığın saniyedeki titreşim sayısı (frekansı) aşağıdakilerden hangisidir?', 'Üç bölü pi Hertz değerinde frekans', ['Altı bölü pi Hertz düzeyinde sıklık', 'On sekiz bölü pi Hertz salınım sayısı', 'Pi bölü üç Hertz titreşim frekansı'], 'a = -omega^2 * x denkleminden omega^2 = 36 ve omega = 6 rad/s bulunur. 2 * pi * f = 6 eşitliğinden f = 3 / pi Hz elde edilir.'),
  ('Harmonik salınım yapan bir cismin bir periyotluk süre zarfında ortalama hız vektörü ve ortalama ivme vektörü için ne söylenebilir?', 'Her iki vektörel büyüklüğün de tam periyot ortalaması sıfırdır', ['Ortalama hız sıfır iken ortalama ivme maksimum ivmenin yarısıdır', 'Ortalama ivme sıfır iken ortalama hız maksimum süratin yarısıdır', 'Her ikisi de tepe değerlerinin pi sayısına bölümü kadardır'], 'Tam bir periyot sonunda cisim başladığı konuma aynı hız vektörüyle döner; net yer değiştirme sıfır olduğundan ortalama hız, net hız değişimi sıfır olduğundan ortalama ivme sıfırdır.'),
  ('Konum-zaman grafiği sinüsoidal olan bir harmonik osilatörün hız-zaman eğrisi ile konum-zaman eğrisi arasındaki faz ilişkisi nasıldır?', 'Hız grafiği konum grafiğinden pi bölü iki radyan ileridedir', ['Hız ve konum grafikleri tüm anlarda aynı fazdadır', 'Hız grafiği konum grafiğinin tam pi radyan gerisindedir', 'Konum grafiği hız grafiğinden pi bölü dört radyan öndedir'], 'x(t) = A sin(wt) alındığında v(t) = dx/dt = wA cos(wt) = wA sin(wt + pi/2) elde edilir; dolayısıyla hız fazı konum fazından pi/2 radyan ileridedir.'),
  ('İçten yanmalı bir motorun silindirindeki piston, krank milinin 3000 devir/dakika hızla dönmesi sırasında yaklaşık basit harmonik hareket yapıyor. Pistonun saniyedeki yön değiştirme sayısı kaçtır?', 'Saniyede yüz kez yön değiştirme hareketi', ['Saniyede elli defa uç nokta dönüşü', 'Saniyede üç bin kez durup kalkma', 'Saniyede iki yüz defa yön terslemesi'], '3000 devir/dakika = 3000 / 60 = 50 Hz frekans demektir. Bir tam periyotta piston alt ve üst ölü noktalarda olmak üzere 2 kez yön değiştirir; saniyede 50 * 2 = 100 kez yön değiştirir.'),
  ('Sürtünmesiz yatay düzlemde -10 cm ile +10 cm arasında basit harmonik hareket yapan bir cisim, +6 cm konumundan geçerken sürati 16 cm/s ölçülüyor. Cismin -8 cm konumundan geçerken sürati kaç cm/s olur?', 'On iki santimetre bölü saniye', ['Yirmi santimetre bölü saniye', 'Sekiz santimetre bölü saniye', 'On dört santimetre bölü saniye'], 'v = omega * karekök(A^2 - x^2) formülünde A = 10 cm ve x1 = 6 cm için 16 = omega * karekök(100 - 36) = 8 * omega -> omega = 2 rad/s bulunur. x2 = -8 cm için v2 = 2 * karekök(100 - 64) = 2 * 6 = 12 cm/s olur.'),
  ('Bir ucu mengene ile masaya tutturulmuş çelik şerit, serbest ucu çekilip bırakıldığında periyodik salınım yapıyor. Şeridin yalnızca ilk çekilme miktarı (küçük açılar sınırında genliği) iki katına çıkarılırsa maksimum hız ve maksimum ivme nasıl değişir?', 'Hem maksimum hız hem de maksimum ivme iki katına çıkar', ['Maksimum hız iki katına çıkarken maksimum ivme dört katına çıkar', 'Periyot iki katına çıktığı için maksimum hız sabit kalır', 'Maksimum ivme iki katına çıkarken maksimum hız kök iki katına çıkar'], 'Basit harmonik harekette periyot ve açısal frekans (omega) genlikten bağımsızdır. v_max = omega * A ve a_max = omega^2 * A olduğundan A iki katına çıkınca ikisi de iki katına çıkar.'),
  ('Bir kuvars kol saatindeki kristal osilatör 32.768 Hz (2^15 Hz) frekansla mekanik-elektriksel harmonik titreşim yapmaktadır. Kristalin art arda iki maksimum uzanım (bir pozitif tepe ile onu izleyen negatif çukur) arasına geçirdiği süre kaç saniyedir?', 'İki üzeri eksi on altı saniyelik zaman aralığı', ['İki üzeri eksi on beş saniyelik tam periyot', 'İki üzeri eksi on dört saniyelik çift çevrim', 'İki üzeri eksi on yedi saniyelik çeyrek periyot'], 'Tam periyot T = 1 / f = 2^(-15) saniyedir. Pozitif uçtan negatif uca geçiş süresi yarım periyot (T/2) olduğundan t = 2^(-15) / 2 = 2^(-16) saniyedir.'),
  ('Aynı doğru üzerinde basit harmonik hareket yapan X ve Y cisimlerinin periyotları sırasıyla 4 s ve 6 s\'dir. İki cisim aynı anda denge konumundan aynı yöne doğru geçtikten en az kaç saniye sonra tekrar aynı anda denge konumundan aynı yönde geçerler?', 'On iki saniyelik ortak kat süresinde', ['Yirmi dört saniyelik çarpım zamanında', 'Altı saniyelik yarım örtüşme anında', 'On saniyelik toplam periyot sonunda'], 'İki cismin aynı konumdan aynı hız yönüyle (aynı fazda) tekrar geçebilmesi için geçen süre periyotlarının en küçük ortak katı olmalıdır: EKOK(4, 6) = 12 saniyedir.'),
  ('Genliği 12 cm olan bir harmonik salınıcı, pozitif uç noktadan bırakıldıktan sonra periyodunun altıda biri (T/6) kadar süre geçtiğinde denge noktasına olan uzaklığı kaç santimetredir?', 'Altı santimetre denge merkezi uzaklığı', ['Altı kök üç santimetre konum değeri', 'Dört santimetre içerideki bölme noktası', 'Sekiz santimetre uzanım koordinatı'], 'Uç noktadan başlayan harekette x(t) = A cos(2*pi*t / T) kullanılır. t = T/6 için x = 12 * cos(pi/3) = 12 * 0,5 = 6 cm bulunur.'),
  ('Hız-zaman grafiği verilen basit harmonik bir harekette, zaman ekseni ile grafik eğrisi arasında sıfırdan T/4\'e (denge konumundan uç noktaya gidiş) kadar kalan taralı alan hangi fiziksel büyüklüğü temsil eder?', 'Hareketin genliğine karşılık gelen maksimum uzanımı', ['Salınım sırasında ulaşılan en büyük ivme şiddetini', 'Cismin birim kütlesine düşen mekanik enerji miktarını', 'Açısal frekans ile periyodun çarpımından gelen sabiti'], 'Hız-zaman grafiğinin altındaki alan yer değiştirmeyi verir. Denge noktasından (x=0) uç noktaya (x=A) gidiş süresindeki (0\'dan T/4\'e) alan doğrudan genlik A\'ya eşittir.'),
  ('Harmonik salınım yapan bir cisim K(-A) ile L(+A) noktaları arasında gidip gelmektedir. Cismin K noktasından serbest bırakıldıktan sonra L noktasına varıncaya kadar geçen sürede ivme vektörünün yönü ve büyüklüğü nasıl değişir?', 'Yönü önce K\'dan L\'ye doğruyken denge noktasından sonra L\'den K\'ya döner; büyüklüğü önce azalıp sıfır olur sonra artar', ['Yönü tüm yarı periyot boyunca K\'dan L\'ye doğru sabit kalır; büyüklüğü düzenli olarak azalır', 'Yönü denge noktasında değişmez ancak büyüklüğü önce maksimuma çıkıp L ucunda sıfırlanır', 'Yönü sürekli L\'den K\'ya doğru olup büyüklüğü K\'dan O\'ya artar, O\'dan L\'ye azalır'], 'K(-A) ile O(0) arasında ivme merkeze yani +x (K\'dan L\'ye) yönündedir ve büyüklüğü sıfıra iner; O\'yu geçip L(+A)\'ya giderken ivme yine merkeze yani -x (L\'den K\'ya) döner ve büyüklüğü artar.'),
  ('Liman girişindeki bir şamandıra, deniz dalgalarının etkisiyle düşeyde periyodu 8 saniye ve genliği 1,5 metre olan basit harmonik hareket yapıyor. Şamandıra en üst tepe noktasından geçtikten 1 saniye sonra denge su seviyesinin kaç metre üzerindedir?', 'Üç kök iki bölü dört metre yükseklikte', ['Üç bölü dört metre su seviyesi üstünde', 'Üç kök üç bölü dört metre düşey konumda', 'Bir tam onda iki metre dalga sırtında'], 'Tepe noktasından başlayan harekette y(t) = A cos(2*pi*t / T) yazılır. A = 1,5 = 3/2 m, T = 8 s ve t = 1 s için y = (3/2) * cos(pi/4) = (3/2) * (kök2 / 2) = 3*kök2 / 4 m olur.'),
  ('Aynı periyotlu iki harmonik hareketten birincisinin genliği A, ikincisinin genliği 3A\'dır. Her iki cisim de kendi denge noktalarından kendi genliklerinin yarısına (birincisi A/2\'ye, ikincisi 3A/2\'ye) ilk kez ulaşırken geçen sürelerin oranı t1/t2 kaçtır?', 'Bir değerine eşit olup süreler özdeştir', ['Bir bölü üç oranında olup birincisi çabuk varır', 'Bir bölü kök üç oranında kareköklü değerdir', 'Üç katı olup birincisi daha yavaş ilerler'], 'Periyotları eşit olan iki BHH\'de x(t) = A_i sin(wt) bağıntısı gereği kendi genliklerinin aynı kesrine (1/2 oranına) ulaşma süreleri T/12 olup genlikten bağımsızdır; oran 1\'dir.'),
  ('Bir parçacık y ekseni boyunca y(t) = 5 + 3 sin(4t) metre denklemine göre hareket etmektedir. Bu parçacığın yaptığı hareketin türü ve genliği hakkında hangisi doğrudur?', 'y = 5 m denge konumu etrafında 3 m genlikli basit harmonik hareket yapar', ['Orijin etrafında 8 m genlikli simetrik basit harmonik hareket yapar', 'y = 3 m denge noktası çevresinde 5 m genlikli periyodik salınım yapar', 'Genliği zamanla artan ve denge konumu kayan harmonik olmayan harekettir'], 'Sabit terim (y_0 = 5 m) denge merkezinin kaydırılmış koordinatını, sinüs fonksiyonunun katsayısı (A = 3 m) ise bu denge merkezi etrafındaki salınım genliğini verir.'),
  ('Kütlesi 400 gram olan bir cisim 0,5 m genlikle basit harmonik hareket yaparken yörüngenin ortasından 2 m/s hızla geçmektedir. Cisim genliğin 0,3 m uzağındaki konumdan geçerken üzerine etkiyen net geri çağırıcı kuvvet kaç Newton\'dur?', 'Bir tam yüzde doksan iki Newton', ['Üç tam onda iki Newton kuvvet', 'Sıfır tam yüzde doksan altı Newton', 'İki tam onda dört Newton şiddeti'], 'v_max = omega * A -> 2 = omega * 0,5 -> omega = 4 rad/s bulunur. x = 0,3 m konumunda net kuvvet F = m * omega^2 * x = 0,4 * 16 * 0,3 = 1,92 N olur.'),
  ('Bir gitardaki kalın Mi teli çekilip bırakıldığında temel modda saniyede 82 tam salınım yapmaktadır. Telin orta noktasının ardışık iki kez anlık olarak durması arasında geçen süre kaç saniyedir?', 'Bir bölü yüz altmış dört saniye', ['Bir bölü seksen iki saniye', 'Bir bölü kırk bir saniye', 'Bir bölü üç yüz yirmi sekiz saniye'], 'Frekans f = 82 Hz olduğundan tam periyot T = 1/82 s\'dir. Salınan tel noktası her yarım periyotta (uç noktalarda) bir kez anlık durur; süre T/2 = 1 / 164 saniyedir.'),
  ('Düzgün çembersel hareket yapan 0,8 m yarıçaplı tekerleğin üzerindeki bir boya lekesi dakikada 150 devir dönmektedir. Yatay paralel ışık altında düşey duvarda oluşan leke gölgesinin maksimum ivmesi kaç m/s^2 olur (pi = 3 alınız)?', 'Yüz seksen metre bölü saniye kare', ['Doksan metre bölü saniye kare', 'Otuz altı metre bölü saniye kare', 'Üç yüz altmış metre bölü saniye kare'], 'f = 150 / 60 = 2,5 Hz\'dir. omega = 2 * pi * f = 2 * 3 * 2,5 = 15 rad/s bulunur. Gölgenin genliği R = 0,8 m olduğundan a_max = omega^2 * R = 225 * 0,8 = 180 m/s^2 olur.'),
  ('Bir laboratuvar simülasyonunda basit harmonik hareket yapan cismin konum-ivme (a-x) grafiğindeki doğrunun yatay eksenle yaptığı geniş açının tanjantı -9 s^(-2) olarak hesaplanıyor. Bu cismin periyodu kaç saniyedir (pi = 3 alınız)?', 'İki saniyelik tam salınım periyodu', ['Üçte iki saniyelik titreşim süresi', 'Altı saniyelik geniş çevrim zamanı', 'Bir saniyelik birim salınım aralığı'], 'a = -omega^2 * x grafiğinin eğimi -omega^2 = -9 s^(-2) olduğundan omega = 3 rad/s\'dir. Periyot T = 2 * pi / omega = (2 * 3) / 3 = 2 saniye bulunur.'),
  ('Bir sismik sensör kütlesi yatayda basit harmonik hareket yaparken t = 0 anında uzanımı negatif (-x), hızı ise pozitif (+v) olarak kaydedilmiştir. Bu sensör kütlesinin t = 0 anındaki ivme yönü ve sürat değişimi nasıldır?', 'İvmesi pozitif yönlüdür ve kütle dengeye yaklaşırken hızlanmaktadır', ['İvmesi negatif yönlüdür ve kütle uç noktaya giderken yavaşlamaktadır', 'İvmesi pozitif yönlüdür ancak kütle zıt yöne çekildiği için yavaşlamaktadır', 'İvmesi negatif yönlüdür ve kütle negatif uca doğru hızlanmaktadır'], 'Uzanım negatif (-x) olduğundan a = -omega^2 * x bağıntısına göre ivme pozitif (+x) yönlüdür. Hız da pozitif (+v) olduğu için hız ve ivme aynı yönlüdür; kütle dengeye doğru hızlanmaktadır.'),
  ('Genliği 40 cm, periyodu 4 saniye olan bir harmonik osilatör t = 0 anında denge merkezinden pozitif yönde geçiyor. t = 0,5 saniye anında osilatörün anlık ivme büyüklüğü kaç cm/s^2 olur (pi = 3 alınız)?', 'Kırk beş kök iki santimetre bölü saniye kare', ['Doksan santimetre bölü saniye kare', 'Kırk beş santimetre bölü saniye kare', 'Otuz kök üç santimetre bölü saniye kare'], 'omega = 2*pi / T = 6 / 4 = 1,5 rad/s\'dir. t = 0,5 s = T/8 anında x = A * sin(2*pi / 8) = 40 * sin(45°) = 20*kök2 cm olur. a = omega^2 * x = (1,5)^2 * 20*kök2 = 2,25 * 20*kök2 = 45*kök2 cm/s^2 bulunur.'),
  ('Basit harmonik salınım yapan bir cismin bir tam periyodu içerisinde, hız vektörü ile ivme vektörünün büyüklükçe sıfırdan farklı ve aynı yönlü olduğu toplam süre periyodun kaçta kaçıdır?', 'Periyodun tam yarısına (T/2) karşılık gelen süre', ['Periyodun dörtte birine (T/4) eşit zaman dilimi', 'Periyodun dörtte üçüne (3T/4) ulaşan toplam aralık', 'Periyodun üçte birine (T/3) denk düşen süre'], 'Bir tam periyodun iki çeyreğinde (+A\'dan O\'ya dönüş ve -A\'dan O\'ya dönüş) cisim hızlanır ve hız ile ivme aynı yönlü olur; T/4 + T/4 = T/2 eder.'),
  ('Bir mühendis, titreşen bir makine parçasının üzerine ivmeölçer ve hız sensörü bağlıyor. Parçanın tepe ivmesi 40 m/s^2 ve tepe hızı 0,8 m/s okunduğuna göre titreşim frekansı kaç Hertz\'dir (pi = 3,14 yerine pi sembolüyle ifade ediniz)?', 'Yirmi beş bölü pi Hertz titreşim sıklığı', ['Elli bölü pi Hertz salınım frekansı', 'On altı bölü pi Hertz devir sayısı', 'Yüz bölü pi Hertz mekanik titreşim'], 'omega = a_max / v_max = 40 / 0,8 = 50 rad/s\'dir. 2 * pi * f = 50 eşitliğinden f = 25 / pi Hz elde edilir.'),
  ('Periyodik her hareket basit harmonik hareket midir sorusunu tartışan öğrencilerden hangisinin verdiği örnek \'periyodik olduğu halde basit harmonik OLMAYAN\' bir harekettir?', 'Tam esnek bir topun sert zemin üzerinde aynı yüksekliğe sürekli zıplayıp düşmesi', ['Sürtünmesiz yatay düzlemde ideal esnek yayın ucundaki kütlenin salınması', 'Küçük açılarla (5 dereceden az) salınan ideal basit sarkacın hareketi', 'Düzgün çembersel hareket yapan bilyenin çap üzerindeki dik izdüşümü'], 'Zıplayan topun hareketi belirli periyotla kendini tekrarlar (periyodiktir), ancak havada ivmesi sabit (-g) olup uzanımla doğru orantılı geri çağırıcı kuvvete (F = -kx) uymaz; bu yüzden BHH değildir.'),
  ('Sürtünmesiz yatay düzlemde basit harmonik hareket yapan bir cismin anlık uzanımı x = -A/kök2 olduğu anda, ivme büyüklüğünün maksimum ivmeye oranı ve hız büyüklüğünün maksimum hıza oranı sırasıyla nedir?', 'Her iki oran da bir bölü kök iki değerine eşittir', ['İvme oranı bir bölü iki, hız oranı kök üç bölü ikidir', 'İvme oranı bir bölü kök iki, hız oranı bir bölü ikidir', 'Her iki oran da tam ikide bir kesrine karşılık gelir'], '|a| / a_max = |x| / A = 1 / kök2\'dir. Hız için ise v / v_max = karekök(1 - x^2/A^2) = karekök(1 - 1/2) = 1 / kök2 bulunur; her iki oran birbirine eşittir.'),
  ('Düzgün çembersel hareket yapan bir noktanın yörüngesi x^2 + y^2 = R^2 çemberidir ve nokta sabit omega açısal hızıyla dönmektedir. Aynı anda hem x ekseni hem de y ekseni üzerindeki dik izdüşümleri incelendiğinde bu iki harmonik hareket arasındaki faz farkı nedir?', 'Birbirine göre çeyrek periyot yani doksan derece faz farkı vardır', ['Her iki eksendeki izdüşüm tam aynı fazda salınım gerçekleştirir', 'Aralarında yarım periyot yani yüz seksen derece zıt faz bulunur', 'Faz farkı açısal hıza bağlı olarak zamanla düzenli artış gösterir'], 'İzdüşümler x(t) = R cos(wt) ve y(t) = R sin(wt) olduğundan kosinüs ile sinüs arasında pi/2 radyan (90° yani T/4) sabit faz farkı vardır.'),
  ('Bir kol saatinin balans çarkı açısal basit harmonik hareket (burulma salınımı) yaparken açısal uzanımı theta(t) = 0,5 cos(4*pi*t) radyan denklemiyle değişiyor. Balans çarkının maksimum açısal hızı kaç rad/s\'dir?', 'İki pi radyan bölü saniye maksimum açısal hız', ['Dört pi radyan bölü saniye tepe dönüş sürati', 'Sekiz pi radyan bölü saniye açısal frekans', 'Yarım pi radyan bölü saniye salınım sürati'], 'Açısal hız d(theta)/dt = -0,5 * 4*pi * sin(4*pi*t) = -2*pi * sin(4*pi*t) rad/s\'dir. Maksimum açısal hız büyüklüğü 2*pi rad/s olur.'),
  ('Sürtünmesiz yatay düzlemde basit harmonik hareket yapan bir cismin periyodu 16 saniyedir. Cisim pozitif uç noktadan bırakıldıktan 6 saniye sonra hız ve ivme vektörlerinin işaretleri nedir?', 'Hız negatif yönlü iken ivme pozitif yönlüdür', ['Hem hız hem de ivme negatif yönü göstermektedir', 'Hız pozitif yönlü iken ivme negatif yönlüdür', 'Hem hız hem de ivme pozitif yönü göstermektedir'], 'T = 16 s için T/4 = 4 s ve T/2 = 8 s\'dir. +A\'dan bırakılan cisim 4. saniyede O\'dan negatif yönde geçer ve 8. saniyeye kadar -A\'ya doğru ilerler. 6. saniyede konum negatiftir (ivme + yönlü), hareket -A\'ya doğrudur (hız - yönlü).'),
  ('Ses hızını ölçmek amacıyla kullanılan bir ultrasonik transdüserin piezoelektrik yüzeyi 40 kHz frekansla ve 1 mikrometre (10^-6 m) genlikle basit harmonik titreşim üretiyor. Yüzeyin maksimum sürati kaç m/s\'dir?', 'Sıfır tam yüzde sekiz pi metre bölü saniye', ['Sıfır tam yüzde dört pi metre bölü saniye', 'Sekiz pi metre bölü saniye tepe hızı', 'Sıfır tam binde sekiz pi metre bölü saniye'], 'v_max = 2 * pi * f * A = 2 * pi * (4 * 10^4) * 10^(-6) = 8 * 10^(-2) * pi = 0,08 pi m/s bulunur.'),
  ('Bir köprü kirişinin rüzgâr altındaki düşey salınımı yaklaşık basit harmonik hareket olarak modelleniyor. Kirişin periyodu yarıya düşerken salınım genliği değişmiyorsa kiriş üzerindeki bir perçinin maruz kaldığı maksimum geri çağırıcı kuvvet nasıl değişir?', 'Dört katına çıkarak perçini daha büyük zorlamaya uğratır', ['İki katına çıkarak periyotla ters orantılı değişir', 'Genlik sabit kaldığı için maksimum kuvvet hiç değişmez', 'Dörtte birine inerek yapısal zorlamayı azaltır'], 'F_max = m * (2*pi / T)^2 * A bağıntısına göre T yarıya indiğinde ve A sabit kaldığında maksimum kuvvet 4 katına çıkar.'),
  ('Atomik kuvvet mikroskobunun (AFM) silikon kantilever ucu 300 kHz frekansla titreşirken numune yüzeyine yaklaştırıldığında salınım genliği 2 nanometreden 1 nanometreye düşüyor ancak frekans sabit tutuluyor. Ucun maksimum ivmesi nasıl değişir?', 'Yarıya inerek önceki değerinin yüzde ellisi olur', ['Dörtte birine düşerek karesel azalma gösterir', 'Frekans sabit tutulduğu için hiç değişmeden kalır', 'İki katına çıkarak yüzey etkileşimini dengeler'], 'a_max = (2*pi*f)^2 * A bağıntısına göre frekans sabitken maksimum ivme genlikle doğru orantılıdır; genlik 2 nm\'den 1 nm\'ye düşünce maksimum ivme yarıya iner.'),
  ('Aralarında r uzaklığı bulunan iki küresel gök cisminin kütleleri ikişer katına çıkarılıp merkezleri arasındaki uzaklık yarıya indirilirse, aralarındaki kütleçekim kuvveti kaç katına çıkar?', '16 katına çıkar', ['8 katına çıkar', '4 katına çıkar', '32 katına çıkar'], 'Kütlelerin çarpımı 2·2 = 4 katına çıkar, uzaklığın karesi (1/2)² = 1/4 katına iner; 4 / (1/4) = 16 kat olur.'),
  ('Homojen yoğunluklu küresel bir gezegenin tam merkezindeki kütleçekim ivmesinin büyüklüğü nedir?', 'Sıfırdır', ['Yüzeydeki değerin yarısına eşittir', 'Yüzeydeki değere eşittir', 'Sonsuz büyüklüktedir'], 'Gezegenin tam merkezinde bulunan bir noktayı her yönden eşit kütleler simetrik olarak çektiği için bileşke çekim alanı sıfır olur.'),
  ('Sabit özkütleli küresel bir gezegenin merkezinden yüzeyine doğru ilerledikçe kütleçekim ivmesinin büyüklüğü merkeze olan uzaklık r ile nasıl değişir?', 'Merkeze olan uzaklık r ile doğru orantılı olarak artar', ['Merkeze olan uzaklık r\'nin karesiyle doğru orantılı artar', 'Merkeze olan uzaklık r ile ters orantılı olarak azalır', 'Merkeze olan uzaklık r boyunca sabit kalır'], 'Sabit özkütleli küre içinde etkin kütle r³ ile, payda r² ile orantılı olduğundan g = (4/3)·π·G·ρ·r bağıntısına göre r ile doğru orantılı artar.'),
  ('Yarıçapı R olan homojen küresel bir gezegenin yüzeyindeki çekim ivmesi g kadardır. Gezegenin merkezinden R/2 uzaklıktaki iç bir noktada çekim ivmesi kaç g olur?', 'g / 2', ['g / 4', '2g', 'g / 8'], 'Homojen küre içinde çekim ivmesi merkeze olan uzaklıkla doğru orantılı olduğundan r = R/2 noktasında ivme g/2 değerini alır.'),
  ('Yarıçapı R olan bir gezegenin yüzeyindeki çekim ivmesi g kadardır. Gezegenin yüzeyinden R kadar yüksekteki bir noktada çekim ivmesi kaç g olur?', 'g / 4', ['g / 2', 'g / 9', 'g / 3'], 'Yüzeyden R kadar yükseklik, gezegen merkezinden 2R uzaklık demektir; dış bölgede ivme uzaklığın karesiyle ters orantılı olduğundan g/(2)² = g/4 olur.'),
  ('İçi tamamen boş, et kalınlığı ihmal edilen homojen küresel bir kabuğun iç bölgesindeki herhangi bir noktada kütleçekim alan şiddeti nasıldır?', 'İç bölgedeki her noktada sıfırdır', ['Merkezde sıfır olup kabuğa yaklaştıkça doğrusal artar', 'Yüzeydeki çekim ivmesine eşit ve sabittir', 'Merkeze yaklaştıkça uzaklığın karesiyle ters orantılı artar'], 'Newton\'un kabuk teoremine göre homojen küresel kabuğun içindeki herhangi bir noktada tüm kütle elemanlarının çekim vektörleri birbirini yok eder ve net alan sıfır olur.'),
  ('Eliptik yörüngede dolanan bir gezegenin yörünge dış merkezliği (eksantrikliği) sıfıra ne kadar yakınsa yörüngenin geometrik şekli neye yaklaşır?', 'Çembere yaklaşır', ['Doğru parçasına yaklaşır', 'Hiperbole yaklaşır', 'Parabole yaklaşır'], 'Dış merkezlik e = c/a sıfıra yaklaştıkça iki odak noktası merkezde çakışır ve elips bir çembere dönüşür.'),
  ('Kepler\'in ikinci yasası olan Alanlar Yasası, temel fizik yasalarından hangisinin doğrudan bir sonucudur?', 'Açısal momentumun korunumu yasasının', ['Çizgisel momentumun korunumu yasasının', 'Kütlenin korunumu yasasının', 'Termodinamiğin ikinci yasasının'], 'Güneş\'in gezegene uyguladığı kütleçekim kuvveti yarıçap vektörü doğrultusunda olduğundan tork sıfırdır; açısal momentum L = m·r²·ω korunur ve dA/dt = L/(2m) sabit kalır.'),
  ('Güneş etrafında eliptik yörüngede dolanan bir gezegen günöte (en uzak) konumundan günberi (en yakın) konumuna doğru ilerlerken kinetik enerjisi ve kütleçekim potansiyel enerjisi nasıl değişir?', 'Kinetik enerjisi artar, potansiyel enerjisi azalır', ['Kinetik enerjisi azalır, potansiyel enerjisi artar', 'Hem kinetik enerjisi hem potansiyel enerjisi artar', 'Hem kinetik enerjisi hem potansiyel enerjisi değişmez'], 'Gezegen Güneş\'e yaklaşırken kütleçekim kuvveti pozitif iş yapar; sürat ve kinetik enerji artarken mekanik enerji korunduğundan potansiyel enerji azalır.'),
  ('Güneş etrafında eliptik yörüngede dolanan bir kuyruklu yıldızın Güneş\'e en yakın uzaklığı r_min, en uzak uzaklığı ise 5·r_min kadardır. Kuyruklu yıldızın en yakın noktadaki çizgisel süratinin en uzak noktadaki çizgisel süratine oranı kaçtır?', '5', ['25', '√5', '1 / 5'], 'Günberi ve günöte noktalarında hız vektörü yarıçap vektörüne diktir; açısal momentum korunumundan m·v₁·r_min = m·v₂·(5·r_min) yazılırsa v₁/v₂ = 5 bulunur.'),
  ('Eliptik yörüngede Güneş etrafında dolanan bir gezegene Güneş\'in uyguladığı kütleçekim kuvvetinin Güneş merkezine göre torku için ne söylenebilir?', 'Yörüngenin her noktasında sıfırdır', ['Günberi noktasında en büyük, günöte noktasında en küçüktür', 'Yalnızca yarı küçük eksen uçlarında sıfırdır', 'Gezegenin hızıyla doğru orantılı olarak sürekli değişir'], 'Kütleçekim kuvvet vektörü her an konum vektörü ile aynı doğrultuda (zıt yönlü) olduğundan aralarındaki açı 180° olup sin180° = 0 nedeniyle tork daima sıfırdır.'),
  ('Aynı yıldız etrafında çembersel yörüngelerde dolanan X ve Y gezegenlerinin yörünge yarıçapları sırasıyla R ve 4R\'dir. X gezegeninin dolanım periyodu T ise Y gezegeninin dolanım periyodu kaç T\'dir?', '8T', ['4T', '16T', '2T'], 'Periyotlar yasası R₁³/T₁² = R₂³/T₂² uygulandığında R³/T² = (4R)³/T_Y² ⇒ T_Y² = 64·T² ⇒ T_Y = 8T elde edilir.'),
  ('Güneş etrafındaki ortalama yörünge yarıçapı Dünya\'nınkinin 9 katı olan varsayımsal bir gezegenin Güneş etrafındaki bir tam dolanımı kaç Dünya yılı sürer?', '27 Dünya yılı', ['9 Dünya yılı', '81 Dünya yılı', '3 Dünya yılı'], 'T² ∝ R³ bağıntısına göre yarıçap 9 katına çıktığında T² = 9³ = 729 olur; karekökü alındığında T = 27 yıl bulunur.'),
  ('Johannes Kepler, gezegen hareketlerine ilişkin üç temel yasasını hangi gökbilimcinin yıllarca teleskopsuz olarak yaptığı son derece duyarlı gözlem verilerini inceleyerek keşfetmiştir?', 'Tycho Brahe', ['Isaac Newton', 'Nicolaus Copernicus', 'Edmond Halley'], 'Kepler, Danimarkalı astronom Tycho Brahe\'nin özellikle Mars gezegeni üzerine biriktirdiği hassas konum ölçümlerini analiz ederek yasalarını formüle etmiştir.'),
  ('Aralarında d uzaklığı bulunan eşit kütleli iki özdeş yıldız, ortak kütle merkezleri etrafında çembersel yörüngede dolanmaktadır. Her bir yıldızın yörünge yarıçapı kaç d\'dir?', 'd / 2', ['d', 'd / 4', '2d'], 'Kütleler eşit olduğundan sistemin kütle merkezi iki yıldızın tam orta noktasındadır; dolayısıyla her yıldız d/2 yarıçaplı çemberde dolanır.'),
  ('Yüzeyindeki çekim ivmesi 10 m/s² olan bir gezegenin merkezinden itibaren uzaklığın 2,5 katına eşit bir dış noktada 4 kg kütleli bir cismin ağırlığı kaç N olur?', '6,4 N', ['16 N', '4 N', '8 N'], 'Merkezden 2,5R uzaklıkta çekim ivmesi g\' = 10 / (2,5)² = 10 / 6,25 = 1,6 m/s² olur; cismin ağırlığı G = m·g\' = 4 · 1,6 = 6,4 N bulunur.'),
  ('Bir gezegenin kütlesi sabit kalmak koşuluyla yarıçapı küçülerek büzülürse, gezegenin tam yüzeyindeki kütleçekim ivmesi nasıl değişir?', 'Yarıçapın karesiyle ters orantılı olarak artar', ['Yarıçapla doğru orantılı olarak azalır', 'Kütle sabit kaldığı için değişmez', 'Yarıçapın küpüyle ters orantılı olarak artar'], 'Kütle M sabit iken g = G·M/R² bağıntısına göre R küçüldüğünde yüzeydeki çekim ivmesi R² ile ters orantılı biçimde büyür.'),
  ('Homojen küresel bir gezegenin merkezinden başlayıp yüzeyin çok dışına kadar uzanan bir eksen boyunca çekim ivmesinin merkeze uzaklığa (r) bağlı grafiği nasıldır?', 'r = R yüzeyine kadar doğrusal artar, r > R bölgesinde parabolik benzeri eğriyle 1/r² ile azalır', ['Merkezden sonsuza kadar sürekli 1/r² ile azalır', 'r = R yüzeyine kadar sabit kalır, r > R bölgesinde doğrusal azalır', 'r = R yüzeyine kadar r² ile artar, r > R bölgesinde 1/r ile azalır'], 'İç bölgede g ∝ r olduğu için grafik orijinden geçen doğru parçasıdır; yüzeyde maksimuma ulaşır ve dış bölgede g ∝ 1/r² ile asimptotik azalır.'),
  ('Dünya\'nın kendi ekseni etrafındaki açısal dönüş hızı şimdikinden daha büyük olsaydı, ekvatorda duran bir cismin dinamometre ile ölçülen görünür ağırlığı nasıl etkilenirdi?', 'Azalırdı', ['Artardı', 'Değişmezdi', 'Önce artar sonra sabitlenirdi'], 'Ekvatorda kütleçekim kuvvetinin bir kısmı m·ω²·R merkezcil ivmesini sağlamaya harcanır; ω artarsa görünür ağırlık m·g - m·ω²·R bağıntısına göre azalır.'),
  ('Dünya yüzeyinde yerçekimi ivmesinin g olduğu bir ortamda periyodu T olan basit bir sarkaç, yüzey çekim ivmesi g/9 olan bir gök cismine götürülürse salınım periyodu kaç T olur?', '3T', ['9T', 'T / 3', 'T'], 'Basit sarkacın periyodu T = 2π·√(L/g) bağıntısıyla çekim ivmesinin kareköküyle ters orantılıdır; ivme g/9 olduğunda periyot √9 = 3 katına çıkar.'),
  ('Yay sabiti k olan esnek bir yayın ucuna m kütleli bir cisim asılarak oluşturulan yay sarkacı Dünya\'dan Ay\'a götürüldüğünde sarkacın titreşim periyodu ve denge uzama miktarı nasıl değişir?', 'Periyodu değişmez, denge uzama miktarı azalır', ['Periyodu artar, denge uzama miktarı azalır', 'Hem periyodu hem denge uzama miktarı azalır', 'Periyodu azalır, denge uzama miktarı değişmez'], 'Yay sarkacının periyodu T = 2π·√(m/k) olup çekim ivmesinden bağımsızdır; ancak denge uzaması x = m·g/k olduğundan Ay\'da g küçüldüğü için uzama azalır.'),
  ('Bir gezegenin etrafında eliptik yörüngede dolanan uydunun yörüngesi üzerinde K, L, M noktalarının gezegen merkezine uzaklıkları r_K < r_L < r_M şeklindedir. Uydunun bu noktalardaki ivme büyüklükleri arasındaki ilişki nedir?', 'a_K > a_L > a_M', ['a_M > a_L > a_K', 'a_K = a_L = a_M', 'a_L > a_K > a_M'], 'Uyduya etki eden tek kuvvet kütleçekim kuvveti olduğundan ivmesi a = G·M/r² bağıntısıyla yalnızca merkeze uzaklığa bağlıdır; uzaklık küçüldükçe ivme büyür.'),
  ('Eşkenar bir üçgenin her bir köşesine m kütleli noktasal gök cisimleri yerleştirilmiştir. İki kütle arasındaki çekim kuvvetinin büyüklüğü F ise, köşelerden birindeki kütleye diğer ikisinin uyguladığı bileşke kütleçekim kuvvetinin büyüklüğü kaç F\'dir?', '√3 · F', ['2F', 'F', '√2 · F'], 'Bir köşedeki kütleye diğer iki köşedeki kütleler eşit büyüklükte F kuvvetleri uygular ve bu kuvvetler arasındaki açı eşkenar üçgende 60° olduğundan bileşke √3·F olur.'),
  ('Dünya\'nın Güneş\'e en yakın olduğu günberi konumu Ocak ayı başında gerçekleşmesine rağmen Kuzey Yarım Küre\'de bu dönemde kış yaşanmasının temel nedeni nedir?', 'Mevsimlerin Güneş\'e uzaklıkla değil, Dünya\'nın eksen eğikliği nedeniyle ışınların düşme açısıyla belirlenmesi', ['Ocak ayında Güneş\'in yüzey sıcaklığının periyodik olarak düşmesi', 'Günberi konumunda Dünya\'nın çizgisel hızının azalması nedeniyle ısınmanın gecikmesi', 'Ay\'ın Ocak ayında Dünya ile Güneş arasına girerek ışınları perdelemesi'], 'Dünya yörüngesinin dış merkezliği çok küçüktür (~0,017); mevsimsel sıcaklık farklarını belirleyen ana etken 23°27\' değerindeki eksen eğikliğidir.'),
  ('Yüzeyindeki çekim ivmesi g olan R yarıçaplı bir gezegenin yüzeyinden h yüksekliğinde çekim ivmesi g / 16 olmaktadır. Buna göre h yüksekliği kaç R\'dir?', '3R', ['4R', '15R', '16R'], 'g\' = g·R²/(R + h)² = g/16 eşitliğinden (R + h)/R = 4 bulunur; buradan R + h = 4R ve yüzeyden yükseklik h = 3R elde edilir.'),
  ('Güneş sistemindeki gezegenlerin Güneş\'e olan ortalama uzaklıkları arttıkça, yörüngedeki dolanım periyotları ve ortalama çizgisel süratleri nasıl değişir?', 'Dolanım periyotları artar, ortalama çizgisel süratleri azalır', ['Dolanım periyotları azalır, ortalama çizgisel süratleri artar', 'Hem dolanım periyotları hem ortalama çizgisel süratleri artar', 'Dolanım periyotları artar, ortalama çizgisel süratleri sabit kalır'], 'Kepler\'in 3. yasasına göre T ∝ R^(3/2) ile periyot artarken, v = √(G·M/R) bağıntısına göre dış gezegenlerin ortalama yörünge sürati azalır.'),
  ('Dünya ile Ay arasındaki kütleçekim kuvveti hakkında yapılan aşağıdaki yorumlardan hangisi doğrudur?', 'Dünya\'nın Ay\'a uyguladığı çekim kuvvetinin büyüklüğü Ay\'ın Dünya\'ya uyguladığına eşittir, ancak Ay\'ın kütlesi küçük olduğundan ivmesi daha büyüktür', ['Dünya\'nın kütlesi çok daha büyük olduğu için Ay\'a daha büyük bir kütleçekim kuvveti uygular', 'Ay\'ın kütlesi küçük olduğu için Dünya üzerinde hiçbir gelgit veya çekim etkisi oluşturamaz', 'İki gök cismi arasındaki kuvvetler eşit büyüklükte ve aynı yönlü olduğundan toplam kuvvet iki katına çıkar'], 'Etki-tepki yasası gereği kuvvet büyüklükleri eşittir; F = m·a bağıntısına göre kütlesi yaklaşık 81 kat küçük olan Ay\'ın merkezcil ivmesi çok daha büyüktür.'),
  ('Aynı yıldız etrafında dolanan X ve Y gezegenlerinin dolanım periyotları oranı T_X / T_Y = 1 / 27\'dir. Buna göre X gezegeninin ortalama yörünge yarıçapının Y gezegenininkine oranı (R_X / R_Y) kaçtır?', '1 / 9', ['1 / 3', '1 / 81', '1 / 27'], 'Kepler\'in üçüncü yasası (R_X / R_Y)³ = (T_X / T_Y)² = (1/27)² = 1 / 729 verir; küpkökü alındığında R_X / R_Y = 1/9 elde edilir.'),
  ('Uluslararası Uzay İstasyonu\'nda (yüzeyden yaklaşık 400 km yüksekte) görev yapan astronotların istasyon içinde "ağırlıksızmış" gibi süzülmelerinin gerçek fiziksel açıklaması nedir?', 'Hem istasyonun hem astronotların Dünya\'nın çekim etkisiyle aynı merkezcil ivmeyle sürekli serbest düşme hareketi yapması', ['400 km yükseklikte Dünya\'nın kütleçekim ivmesinin tamamen sıfırlanmış olması', 'İstasyon kabinindeki vakum pompalarının yerçekimini yapay olarak yok etmesi', 'Ay\'ın çekim kuvvetinin 400 km irtifada Dünya\'nın çekim kuvvetini tam dengelemesi'], '400 km irtifada yerçekimi ivmesi yüzeydekinin yaklaşık %88\'i kadardır; astronot ve kabin aynı ivmeyle yörüngede serbest düştüğü için yüzeye tepki kuvveti oluşmaz.'),
  ('Yarıçapları R_K = R ve R_L = 3R olan homojen K ve L kürelerinin yüzeylerindeki kütleçekim ivmeleri birbirine eşittir. Buna göre K küresinin özkütlesinin L küresinin özkütlesine oranı (d_K / d_L) kaçtır?', '3', ['9', '1 / 3', '27'], 'Homojen küre yüzeyinde g = (4/3)·π·G·d·R bağıntısı geçerlidir; g_K = g_L olduğundan d_K·R = d_L·(3R) ⇒ d_K / d_L = 3 elde edilir.'),
  ('Güneş etrafında eliptik yörüngede dolanan bir gezegen için bir tam dolanım süresince aşağıdaki fiziksel büyüklüklerden hangileri korunur (sabit kalır)?', 'Toplam mekanik enerji ve Güneş\'e göre açısal momentum', ['Çizgisel hız ve kinetik enerji', 'Kütleçekim potansiyel enerjisi ve çizgisel momentum', 'Merkezcil ivme büyüklüğü ve yörünge eğrilik yarıçapı'], 'Sürtünmesiz uzayda korunumlu merkezi kuvvet altında toplam mekanik enerji ve merkeze göre tork sıfır olduğundan açısal momentum sabit kalır.'),
  ('Kütlesi Dünya\'nın kütlesinin 2 katı, yarıçapı Dünya\'nın yarıçapının 2 katı olan bir ötegezegenin yüzeyindeki kütleçekim ivmesi, Dünya yüzeyindeki çekim ivmesi g\'nin kaç katıdır?', '1 / 2 katıdır', ['1 katıdır', '2 katıdır', '1 / 4 katıdır'], 'g\' = G·(2M) / (2R)² = (2/4)·(G·M/R²) = (1/2)·g bulunur.'),
  ('Bir gezegenin kendi ekseni etrafında dönmediği ve tam küresel olduğu varsayılırsa, yüzeyindeki tüm noktalarda kütleçekim ivmesinin büyüklüğü için ne söylenebilir?', 'Yüzeydeki tüm noktalarda eşit büyüklüktedir', ['Ekvatorda en küçük, kutuplarda en büyüktür', 'Kuzey yarım kürede güney yarım küreden daha büyüktür', 'Yalnızca ekvator çizgisi üzerinde sıfırdır'], 'Geoit basıklığı ve dönme kaynaklı merkezkaç etki olmadığında, homojen küresel gezegenin yüzeyindeki her nokta merkeze eşit R uzaklıkta olduğundan çekim ivmesi her yerde eşittir.'),
  ('Dünya etrafında çembersel yörüngede dolanan bir uydunun yörünge yarıçapı daha yüksek bir irtifaya çıkarılırsa çizgisel hızı ve açısal hızı nasıl değişir?', 'Hem çizgisel hızı hem açısal hızı azalır', ['Çizgisel hızı artar, açısal hızı azalır', 'Çizgisel hızı azalır, açısal hızı artar', 'Hem çizgisel hızı hem açısal hızı artar'], 'Yörünge yarıçapı r arttığında v = √(G·M/r) gereği çizgisel hız azalır; ω = v/r = √(G·M/r³) gereği açısal hız daha da hızlı biçimde azalır.'),
  ('Bir gezegenin etrafında r ve 9r yarıçaplı çembersel yörüngelerde dolanan K ve L uydularının çizgisel süratlerinin oranı (v_K / v_L) kaçtır?', '3', ['9', '1 / 3', '√3'], 'Çizgisel yörünge hızı yarıçapın kareköküyle ters orantılıdır: v_K / v_L = √(9r / r) = 3 bulunur.'),
  ('Dünya yüzeyinden alınan bir uydu daha yüksek bir yörüngeye çıkarıldığında Dünya-uydu sisteminin kütleçekim potansiyel enerjisi nasıl değişir?', 'Artar (sıfıra yaklaşır)', ['Azalır (daha negatif olur)', 'Önce azalır sonra sabit kalır', 'Değişmez'], 'E_p = -G·M·m/r bağıntısında r büyüdüğünde kesrin mutlak değeri küçülür, ancak önündeki eksi işaretinden dolayı potansiyel enerji cebirsel olarak artar.'),
  ('Kütlesi M olan bir gezegenin etrafında r yarıçaplı çembersel yörüngede dolanan m kütleli bir uydunun toplam mekanik enerjisi nedir?', '-G·M·m / (2r)', ['-G·M·m / r', 'G·M·m / (2r)', 'Sıfır'], 'Toplam mekanik enerji E_top = E_k + E_p = G·M·m/(2r) + (-G·M·m/r) = -G·M·m/(2r) olur.'),
  ('Çembersel yörüngede dolanan bir uydunun kinetik enerjisi E_k, potansiyel enerjisi E_p ve toplam mekanik enerjisi E_top arasındaki cebirsel ilişki hangisinde doğru verilmiştir?', 'E_top = -E_k = E_p / 2', ['E_top = E_k = -E_p', 'E_top = 2·E_k = -E_p', 'E_top = -2·E_k = E_p'], 'E_k = G·M·m/(2r), E_p = -G·M·m/r ve E_top = -G·M·m/(2r) olduğundan E_top = -E_k ve E_top = E_p / 2 eşitliği her çembersel yörüngede geçerlidir.'),
  ('Dünya etrafında çembersel yörüngede dolanan bir uydunun kinetik enerjisi 4·10⁹ J olarak hesaplanmıştır. Bu uydunun bulunduğu yörüngedeki kütleçekim potansiyel enerjisi ve toplam mekanik enerjisi sırasıyla kaç J\'dir?', '-8·10⁹ J ve -4·10⁹ J', ['-4·10⁹ J ve 0 J', '-2·10⁹ J ve 2·10⁹ J', '8·10⁹ J ve 12·10⁹ J'], 'Çembersel yörüngede E_p = -2·E_k = -8·10⁹ J ve E_top = -E_k = -4·10⁹ J olur.'),
  ('Yarıçapı R, kütlesi M olan bir gezegenin tam yüzeyinde durmakta olan m kütleli bir roketin gezegene olan bağlanma enerjisi ile gezegen etrafında R yarıçaplı alçak yörüngede dolanan m kütleli uydunun bağlanma enerjisi karşılaştırıldığında ne görülür?', 'Yüzeyde duran roketin bağlanma enerjisi, yörüngede dolanan uydunun bağlanma enerjisinin 2 katıdır', ['İkisinin bağlanma enerjileri birbirine eşittir', 'Yörüngede dolanan uydunun bağlanma enerjisi yüzeyde duran roketinkinin 2 katıdır', 'Yüzeyde duran roketin kinetik enerjisi sıfır olduğundan bağlanma enerjisi de sıfırdır'], 'Yüzeyde duran roketin toplam enerjisi -G·M·m/R olduğundan bağlanma enerjisi G·M·m/R\'dir; yörüngedeki uydunun toplam enerjisi -G·M·m/(2R) olduğundan bağlanma enerjisi G·M·m/(2R)\'dir.'),
  ('Atmosfersiz küresel bir gezegenin yüzeyindeki kütleçekim ivmesi g ve yarıçapı R cinsinden gezegenin yüzeyinden kurtulma hızı hangi ifadeye eşittir?', '√(2·g·R)', ['√(g·R)', '2·√(g·R)', 'g·R²'], 'Kurtulma hızı bağıntısı v_k = √(2·G·M/R) içinde G·M = g·R² yerine konulursa v_k = √(2·g·R) elde edilir.'),
  ('Atmosferi olmayan bir gezegenin yüzeyinden m kütleli bir cisim düşey doğrultuda v_k kurtulma hızıyla fırlatılmak yerine yüzeyle 45° açı yapacak biçimde fırlatılırsa kurtulma hızının büyüklüğü nasıl değişir?', 'Değişmez, yine v_k kadardır', ['√2 katına çıkar', '1/√2 katına iner', '2 katına çıkar'], 'Enerji skaler bir büyüklüktür; cisim gezegene çarpmayacak herhangi bir dış doğrultuda fırlatıldığında kurtulma şartı yalnızca kinetik enerjinin büyüklüğüne bağlıdır, fırlatma açısına bağlı değildir.'),
  ('Bir gezegenin tam yüzeyine çok yakın çembersel yörüngede dolanan bir uydunun yörünge hızı v_y, aynı gezegenin yüzeyinden kurtulma hızı ise v_k\'dir. Buna göre v_k / v_y oranı kaçtır?', '√2', ['2', '1 / √2', '4'], 'Yüzeye yakın yörünge hızı v_y = √(G·M/R), kurtulma hızı v_k = √(2·G·M/R) olduğundan ikisinin oranı her gezegen için √2\'dir.'),
  ('Dünya\'nın yüzeyinden kurtulma hızı yaklaşık 11,2 km/s\'dir. Kütlesi Dünya\'nın kütlesinin 4 katı, yarıçapı ise Dünya\'nın yarıçapına eşit olan bir gezegenin yüzeyinden kurtulma hızı yaklaşık kaç km/s olur?', '22,4 km/s', ['44,8 km/s', '11,2 km/s', '5,6 km/s'], 'v_k = √(2·G·M/R) bağıntısına göre yarıçap sabitken kütle 4 katına çıkarsa kurtulma hızı √4 = 2 katına çıkar; 2 · 11,2 = 22,4 km/s olur.'),
  ('Yer sabit (jeostasyoner) bir uydunun yörünge düzlemi mutlaka Dünya\'nın hangi coğrafi düzlemiyle çakışık olmak zorundadır?', 'Ekvator düzlemiyle', ['Başlangıç meridyeni düzlemiyle', 'Yengeç dönencesi düzlemiyle', 'Tutulum (ekliptik) düzlemiyle'], 'Merkezcil kuvvet olan kütleçekim kuvveti Dünya\'nın merkezine yöneliktir; uydunun hep aynı enlem üzerinde sabit kalabilmesi için yörünge merkezinin Dünya merkeziyle çakıştığı tek dönme düzlemi ekvator düzlemidir.'),
  ('Yer sabit (jeostasyoner) uyduların Dünya\'nın dönüş yönüne göre dolanım yönü ve yörünge yarıçapı hakkında aşağıdakilerden hangisi doğrudur?', 'Batıdan doğuya doğru, tüm yer sabit uydular için tek ve belirli bir yörünge yarıçapında dolanırlar', ['Doğudan batıya doğru, uydunun kütlesine göre değişen farklı yarıçaplarda dolanırlar', 'Kuzeyden güneye doğru, atmosferin hemen üst sınırında dolanırlar', 'Batıdan doğuya doğru, verici gücüne bağlı olarak seçilen rastgele yüksekliklerde dolanırlar'], 'Periyot T = 24 saat sabit olduğunda R³ = G·M·T²/(4π²) bağıntısı tek bir yörünge yarıçapı (merkezden ~42.164 km, yüzeyden ~35.786 km) verir ve dönüş yönü Dünya ile aynı (batıdan doğuya) olmalıdır.'),
  ('Türkiye\'deki evlerin çanak antenlerinin (Türksat uydularını gören antenlerin) sürekli hareket etmeyip hep güney yönünde sabit bir noktaya ayarlanabilmesinin fiziksel nedeni nedir?', 'Türksat uydularının ekvator üzerinde yer sabit (jeostasyoner) yörüngede Dünya ile eş açısal hızla dönmesi', ['Türksat uydularının tam Türkiye\'nin coğrafi dikey hizasında uzayda asılı durması', 'Çanak antenlerin içindeki motorların uyduyu gün boyu görünmez biçimde takip etmesi', 'Uyduların Dünya\'dan çok uzakta olması nedeniyle hareketlerinin binlerce yılda bir fark edilmesi'], 'Türkiye Kuzey Yarım Küre\'de yer aldığından ekvator düzlemindeki yer sabit uydular güney ufkuna doğru sabit bir yükselti ve azimut açısında hareketsiz görünür.'),
  ('Yarıçapı R, kütlesi M olan bir gezegenin yüzeyinde duran m kütleli bir uyduyu gezegenin yüzeyinden R kadar yüksekteki (merkezden 2R uzaklıktaki) çembersel bir yörüngeye oturtmak için uyduya verilmesi gereken en küçük enerji kaç G·M·m / R\'dir?', '3/4 · G·M·m / R', ['1/2 · G·M·m / R', '1/4 · G·M·m / R', 'G·M·m / R'], 'Yüzeyde ilk enerji E_ilk = -G·M·m/R (dönme ihmal); merkezden 2R yarıçaplı çembersel yörüngede son toplam enerji E_son = -G·M·m/(2·2R) = -G·M·m/(4R); fark ΔE = E_son - E_ilk = (-1/4 - (-1))·G·M·m/R = (3/4)·G·M·m/R olur.'),
  ('Merkezden r uzaklıktaki çembersel yörüngede dolanan m kütleli bir uyduyu merkezden 2r uzaklıktaki başka bir çembersel yörüngeye çıkarmak için yapılması gereken en az iş kaç G·M·m / r kadardır?', '1/4 · G·M·m / r', ['1/2 · G·M·m / r', 'G·M·m / r', '3/4 · G·M·m / r'], 'İlk yörüngede E₁ = -G·M·m/(2r), ikinci yörüngede E₂ = -G·M·m/(4r); gereken iş W = E₂ - E₁ = -1/(4r)·G·M·m + 1/(2r)·G·M·m = (1/4)·G·M·m/r bulunur.'),
  ('Işığın bile kütleçekim alanından kaçamadığı, yani yüzeyinden (olay ufkundan) kurtulma hızının ışık hızına eşit veya ondan büyük olduğu aşırı yoğun gök cisimlerine ne ad verilir?', 'Kara delik', ['Beyaz cüce', 'Kırmızı dev', 'Bulutsu'], 'Bir gök cisminin kütlesi Schwarzschild yarıçapının içine sıkıştığında kurtulma hızı c ışık hızına ulaşır ve bu gök cismine kara delik denir.'),
  ('Çembersel yörüngede v hızıyla dolanan bir uydunun roket motorları anlık olarak ateşlenip hızı hareket yönünde √2 · v değerine çıkarılırsa uydunun bundan sonraki yörüngesi nasıl olur?', 'Parabolik bir açık yörünge izleyerek gezegenin çekim alanından bir daha dönmemek üzere kurtulur', ['Yarıçapı iki kat büyük yeni bir çembersel yörüngede dolanmaya başlar', 'Eliptik bir kapalı yörüngeye yerleşerek periyodik dolanımını sürdürür', 'Merkeze doğru sarmal çizerek gezegen yüzeyine düşer'], 'r uzaklığında çembersel hız v = √(G·M/r) iken kurtulma hızı √(2·G·M/r) = √2·v değerindedir; toplam mekanik enerji sıfır olur ve parabolik kaçış yörüngesi izler.'),
  ('Aynı gezegen etrafında çembersel yörüngelerde dolanan eşit kütleli X ve Y uydularının yörünge yarıçapları sırasıyla r ve 3r\'dir. X uydusunun kinetik enerjisinin Y uydusunun kinetik enerjisine oranı (E_kX / E_kY) kaçtır?', '3', ['9', '1 / 3', '√3'], 'Kütleleri eşit olan uydular için E_k = G·M·m / (2r) bağıntısına göre kinetik enerji yörünge yarıçapıyla ters orantılıdır; r_Y / r_X = 3r / r = 3 olur.'),
  ('Aynı gezegen etrafında r ve 2r yarıçaplı çembersel yörüngelerde dolanan K (kütlesi 2m) ve L (kütlesi m) uydularının gezegene göre açısal momentumlarının büyüklükleri oranı (L_K / L_L) kaçtır?', '√2', ['2', '2√2', '1'], 'Çembersel yörüngede L = m·v·r = m·√(G·M/r)·r = m·√(G·M·r) olur; L_K / L_L = (2m / m) · √(r / 2r) = 2 / √2 = √2 bulunur.'),
  ('Çembersel yörüngede dolanan bir uydu üzerinde Dünya\'nın uyguladığı kütleçekim kuvvetinin yaptığı net iş neden sıfırdır?', 'Kütleçekim kuvvet vektörü her an uydunun anlık hız (yer değiştirme) vektörüne dik olduğu için', ['Yörünge yüksekliğinde kütleçekim kuvvetinin büyüklüğü sıfır olduğu için', 'Uydunun güneş panelleri harcanan işi sürekli elektrik enerjisiyle telafi ettiği için', 'Merkezkaç kuvvet kütleçekim kuvvetini yok ederek net kuvveti sıfırladığı için'], 'Çembersel yörüngede kuvvet merkeze, hız ise teğet doğrultudadır; aralarındaki açı 90° olduğundan W = F·Δx·cos90° = 0 olur ve kinetik enerji değişmez.'),
  ('Kenar uzunluğu d olan eşkenar üçgenin köşelerine m kütleli üç özdeş gök cismi sonsuzdan getirilerek yerleştirilmiştir. Oluşan bu üçlü sistemin toplam kütleçekim potansiyel enerjisi nedir?', '-3·G·m² / d', ['-G·m² / d', '-3·G·m² / d²', '-6·G·m² / d'], 'Üç kütleden oluşturulabilecek ikili etkileşim çifti sayısı 3\'tür ((1-2), (2-3), (1-3)); her çiftin potansiyel enerjisi -G·m²/d olduğundan toplam potansiyel enerji -3·G·m²/d olur.'),
  ('Alçak Dünya yörüngesinde (yüzeyden yaklaşık 300-500 km yüksekte) dolanan kutupsal gözlem uydularının bir tam dolanım periyodu yaklaşık ne kadardır?', 'Yaklaşık 90 dakika', ['Yaklaşık 24 saat', 'Yaklaşık 12 saat', 'Yaklaşık 27,3 gün'], 'Dünya yarıçapının (~6370 km) hemen üzerindeki alçak yörüngelerde T = 2π·√(r³/(G·M)) bağıntısı yaklaşık 88-95 dakikalık bir dolanım süresi verir.'),
  ('Yüzeyindeki kütleçekim ivmesi g olan R yarıçaplı bir gezegenin yüzeyine çok yakın çembersel yörüngede dolanan bir uydunun çizgisel hızı g ve R cinsinden nedir?', '√(g · R)', ['√(2 · g · R)', 'g · R', '√(g / R)'], 'v = √(G·M/R) bağıntısında G·M = g·R² yerine konulduğunda yüzeye teğet yakın yörünge hızı v = √(g·R) bulunur.'),
  ('Dünya yarıçapı R ≈ 6400 km ve yüzeydeki yerçekimi ivmesi g ≈ 10 m/s² olarak alındığında, Dünya yüzeyine çok yakın alçak çembersel yörüngede dolanabilecek bir uydunun hızı yaklaşık kaç km/s olur?', '8 km/s', ['11,2 km/s', '4 km/s', '16 km/s'], 'R = 6,4·10⁶ m ve g = 10 m/s² için v = √(g·R) = √(10 · 6,4·10⁶) = √(64·10⁶) = 8000 m/s = 8 km/s bulunur.'),
  ('Kütleçekim potansiyeli (birim kütle başına düşen kütleçekim potansiyel enerjisi) V = -G·M/r olarak tanımlanır. Kütleçekim potansiyelinin SI birim sistemindeki birimi aşağıdakilerden hangisine eşdeğerdir?', 'J / kg (veya m² / s²)', ['N / kg (veya m / s²)', 'J · kg', 'N · m² / kg'], 'Potansiyel V = E_p / m olduğundan birimi Joule / kilogram\'dır; J = kg·m²/s² açıldığında m²/s² birimine eşdeğer olduğu görülür.'),
  ('Bir gezegenin etrafındaki aynı eş potansiyel küre yüzeyi üzerinde bulunan K noktasından L noktasına m kütleli bir uydu yavaşça taşındığında kütleçekim kuvvetinin yaptığı net iş nedir?', 'Sıfırdır', ['G·M·m / R kadardır', '-G·M·m / (2R) kadardır', 'K-L yayının uzunluğu ile doğru orantılıdır'], 'Eş potansiyel yüzey üzerindeki tüm noktalarda potansiyel aynı olduğundan ΔV = 0 ve ΔE_p = m·ΔV = 0 olur; dolayısıyla kütleçekim kuvvetinin yaptığı net iş sıfırdır.'),
  ('Güneş-Dünya sistemi gibi büyük iki gök cisminin kütleçekim ve merkezkaç etkilerinin dengelenmesiyle üçüncü küçük bir uydunun iki cisme göre sabit konumunu koruyabildiği uzaydaki özel denge noktalarına (James Webb Uzay Teleskobu\'nun bulunduğu L2 noktası gibi) ne ad verilir?', 'Lagrange noktaları', ['Roche limiti noktaları', 'Schwarzschild odakları', 'Van Allen kuşakları'], 'İki büyük gök cisminin ortak dönen referans çerçevesinde küçük bir kütlenin bağıl dengede kalabildiği L1, L2, L3, L4 ve L5 olarak adlandırılan 5 özel konuma Lagrange noktaları denir.'),
  ('Güneş sistemindeki gezegenlerden Merkür\'ün yörünge süratinin (~47 km/s) Neptün\'ün yörünge süratinden (~5,4 km/s) çok daha büyük olmasının temel nedeni nedir?', 'Merkür\'ün Güneş\'e çok daha yakın bir yörüngede bulunması nedeniyle daha büyük kütleçekimsel merkezcil ivmeye maruz kalması', ['Merkür\'ün kütlesinin Neptün\'ün kütlesinden çok daha büyük olması', 'Merkür\'ün atmosferi olmadığı için uzayda sürtünmeyle karşılaşmaması', 'Neptün\'ün çok sayıda uydusunun gezegeni geriye doğru çekerek yavaşlatması'], 'Yörünge sürati v = √(G·M_Güneş / r) gezegenin kütlesinden bağımsızdır ve yalnız Güneş\'e uzaklık r ile ters karekök ilişkisi gösterir; Güneş\'e en yakın gezegen olan Merkür en hızlı dolanır.'),
  ('Kütleleri farklı m₁ ve m₂ (m₁ > m₂) olan iki uydu, Dünya merkezinden eşit r uzaklıktaki aynı çembersel yörüngede dolanmaktadır. Bu iki uydu için aşağıdaki niceliklerden hangisi birbirine eşit değildir?', 'Kinetik enerjileri', ['Çizgisel süratleri', 'Dolanım periyotları', 'Merkezcil ivme büyüklükleri'], 'Aynı r yarıçapında hız v = √(G·M/r), periyot T = 2πr/v ve merkezcil ivme a = G·M/r² kütleden bağımsız olup eşittir; ancak kinetik enerji (1/2)m·v² kütleye doğrudan bağlı olduğu için m₁ > m₂ iken eşit değildir.'),
  ('Yarıçapı R olan bir gezegenin yüzeyinden 3R yükseklikte çembersel yörüngede dolanan bir uydunun yörünge hızı v kadardır. Bu gezegenin tam yüzeyinden kurtulma hızı kaç v\'dir?', '2√2 · v', ['2v', '4v', '√2 · v'], 'Yüzeyden 3R yükseklik merkezden 4R uzaklıktır: v = √(G·M/(4R)) = (1/2)·√(G·M/R) ⇒ √(G·M/R) = 2v. Yüzeyden kurtulma hızı v_k = √(2·G·M/R) = √2 · √(G·M/R) = 2√2 · v bulunur.'),
  ('Güneş sisteminden tamamen ayrılmak üzere Dünya yörüngesinden (Güneş\'e 1 AB uzaklıktan) fırlatılan bir uzay aracının, yalnızca Dünya çekiminden değil Güneş\'in kütleçekim alanından da kaçabilmesi için Güneş\'e göre sahip olması gereken minimum hız, Dünya\'nın yörünge hızı v_D\'nin kaç katıdır?', '√2 katı', ['2 katı', '4 katı', '1 / √2 katı'], 'Dünya Güneş etrafında r = 1 AB yarıçaplı yaklaşık çembersel yörüngede v_D = √(G·M_Güneş / r) hızıyla dolanır; aynı uzaklıktan Güneş\'in çekiminden kurtulma hızı √(2·G·M_Güneş / r) = √2 · v_D olur.'),
  ('Kütleleri M ve 2M, yarıçapları sırasıyla R ve 2R olan iki gezegenin yüzeylerinden kurtulma hızları v₁ ve v₂\'dir. Buna göre v₁ / v₂ oranı kaçtır?', '1', ['1 / 2', '√2', '1 / √2'], 'v₁ = √(2·G·M / R) ve v₂ = √(2·G·(2M) / (2R)) = √(2·G·M / R) olduğundan her iki gezegenin kurtulma hızları birbirine eşittir ve oran 1\'dir.'),
  ('Yörüngede dolanan bir uzay istasyonunun dışına çıkan bir astronot, elindeki İngiliz anahtarını istasyona göre ilk hızsız olarak yavaşça serbest bırakırsa anahtar nasıl hareket eder?', 'Uzay istasyonu ile aynı yörüngede ve aynı hızla yan yana dolanmaya devam eder', ['Anında dikey bir doğru boyunca Dünya yüzeyine doğru hızla düşer', 'İstasyonun gerisinde kalarak ters yönde dönmeye başlar', 'Uzay boşluğuna doğru düz bir çizgide uzaklaşır'], 'Serbest bırakılan anahtar başlangıçta istasyonla aynı konum ve aynı yörünge hızına sahiptir; kütle yörünge hızını etkilemediği için istasyonla birlikte aynı yörüngede dolanmayı sürdürür.'),
  ('Güneş sistemindeki bir gezegenin kütlesini doğrudan ve yüksek doğrulukla hesaplamak isteyen gökbilimciler için en elverişli gözlemsel durum hangisidir?', 'Gezegenin etrafında dolanan doğal veya yapay bir uydunun bulunması ve bu uydunun yörünge yarıçapı ile periyodunun ölçülmesi', ['Gezegenin yalnızca Güneş etrafındaki dolanım periyodunun ölçülmesi', 'Gezegenin yüzey renginin ve yansıtma çarpanının (albedo) teleskopla belirlenmesi', 'Gezegenin kendi ekseni etrafındaki dönüş süresinin ölçülmesi'], 'Bir gezegenin Güneş etrafındaki periyodu yalnızca Güneş\'in kütlesini verir; gezegenin kendi kütlesini bulmak için onun etrafında dolanan bir uydunun r ve T değerlerini r³/T² = G·M_gezegen/(4π²) bağıntısında kullanmak gerekir.'),
  ('K-O-L noktaları arasında basit harmonik hareket yapan bir cismin O denge noktasındaki hızı 10 m/s\'dir. Genlik 50 cm olduğuna göre cismin maksimum ivmesi kaç m/s²\'dir?', '200 m/s²', ['100 m/s²', '50 m/s²', '400 m/s²'], 'v_maks = ω·r => 10 = ω · 0,5 => ω = 20 rad/s bulunur. Maksimum ivme a_maks = ω²·r = 400 · 0,5 = 200 m/s² olur.'),
  ('Genliği 10 cm olan basit harmonik hareket yapan bir cismin denge noktasından 6 cm uzaklıktaki hızı 16 cm/s olduğuna göre, açısal hızı kaç rad/s\'dir?', '2 rad/s', ['4 rad/s', '1,6 rad/s', '3,2 rad/s'], 'v = ω·√(r² - x²) bağıntısından 16 = ω·√(10² - 6²) = ω·√64 = 8ω bulunur, buradan ω = 2 rad/s çıkar.'),
  ('K-L noktaları arasında basit harmonik hareket yapan noktasal cisim, KO ve OL aralıklarını ikişer eşit parçaya bölen M ve N noktalarından geçmektedir (K-M-O-N-L). Cismin K\'den M\'ye gelme süresi t₁, M\'den O\'ya gelme süresi t₂ ise t₁/t₂ oranı kaçtır?', '2', ['1', '3', '1/2'], 'Düzgün çembersel izdüşümde K-M arası 60° (T/6), M-O arası 30° (T/12) açı tarar; dolayısıyla t₁/t₂ = (T/6)/(T/12) = 2 olur.'),
  ('Uzanım denklemi x(t) = 0,8·sin(5π·t) (metre, saniye) olan basit harmonik hareketlinin frekansı ve maksimum hızı aşağıdakilerden hangisinde doğru verilmiştir? (π = 3 alınız.)', '2,5 Hz ve 12 m/s', ['5 Hz ve 12 m/s', '2,5 Hz ve 4 m/s', '0,4 Hz ve 15 m/s'], 'ω = 2πf = 5π => f = 2,5 Hz bulunur. r = 0,8 m ve ω = 5·3 = 15 rad/s olduğundan v_maks = 15 · 0,8 = 12 m/s elde edilir.'),
  ('Maksimum hızı 6 m/s ve maksimum ivmesi 18 m/s² olan basit harmonik hareketlinin genliği kaç metredir?', '2 metre', ['3 metre', '0,5 metre', '1,5 metre'], 'a_maks / v_maks = (ω²·r) / (ω·r) = ω => ω = 18 / 6 = 3 rad/s. v_maks = ω·r => 6 = 3·r => r = 2 m bulunur.'),
  ('Basit harmonik harekette hız-uzanım grafiği çizildiğinde elde edilen geometrik şekil aşağıdakilerden hangisidir?', 'Merkezi orijinde olan elips', ['Orijinden geçen negatif eğimli düz bir doğru', 'Kolları yukarı bakan ikinci dereceden parabol', 'Birinci ve üçüncü bölgede yer alan ikizkenar hiperbol'], 'v² = ω²(r² - x²) denklemi düzenlendiğinde x²/r² + v²/(ωr)² = 1 elips denklemi elde edilir.'),
  ('Periyodu 1,2 saniye olan bir basit harmonik hareketli, denge konumundan (+x) yönünde geçtikten 0,5 saniye sonra hangi konumda ve hangi yönde hareket ediyor olur? (Genlik = r)', '+r/2 konumunda, denge noktasına (-x) doğru', ['+r/2 konumunda, uç noktaya (+x) doğru', '+r√3/2 konumunda, denge noktasına (-x) doğru', '-r/2 konumunda, uç noktaya (-x) doğru'], 'T = 1,2 s ise T/4 = 0,3 s\'de +r ucuna varır. Kalan 0,2 s = T/6 sürede +r ucundan geri dönerek +r/2 konumuna gelir ve yönü dengeye (-x) doğrudur.'),
  ('Aynı yatay düzlemde basit harmonik hareket yapan X ve Y cisimlerinin kütleleri eşit, genlikleri sırasıyla r ve 2r, periyotları ise T ve 2T\'dir. Cisimlerin maksimum geri çağırıcı kuvvetlerinin büyüklükleri oranı F_X / F_Y kaçtır?', '2', ['1', '4', '1/2'], 'F_maks = m·(2π/T)²·r bağıntısından F_X / F_Y = (r / T²) / (2r / 4T²) = 1 / (1/2) = 2 bulunur.'),
  ('K-L noktaları arasında 18 saniye periyotla basit harmonik hareket yapan bir cisim, denge noktası O\'dan L\'ye doğru geçtikten 12 saniye sonra nerede bulunur? (|KO| = |OL| = r)', 'K ile O arasında, O\'dan r√3/2 uzakta', ['O ile L arasında, O\'dan r/2 uzakta', 'Tam K uç noktasında anlık durgun', 'K ile O arasında, O\'dan r/2 uzakta'], 'x(t) = r·sin(2πt/T) => t = 12 s ve T = 18 s için açı (2π·12)/18 = 4π/3 rad = 240° olur. sin(240°) = -√3/2 olduğundan konum K-O arasında O\'dan r√3/2 uzaktadır.'),
  ('Hız denklemi v(t) = 24·cos(4t) (m/s, saniye) olan basit harmonik hareketlinin genliği ve maksimum ivmesi aşağıdakilerden hangisidir?', '6 m ve 96 m/s²', ['6 m ve 48 m/s²', '4 m ve 96 m/s²', '12 m ve 48 m/s²'], 'v(t) = v_maks·cos(ωt) olduğundan ω = 4 rad/s ve v_maks = ω·r = 24 m/s => 4r = 24 => r = 6 m olur. Maksimum ivme a_maks = ω²·r = 16 · 6 = 96 m/s² bulunur.'),
  ('Düşey düzlemde düzgün çembersel hareket yapan bir bilyenin yatay perde üzerindeki gölgesi 20 cm genlikli basit harmonik hareket yapmaktadır. Bilyenin merkezcil ivmesi 5 m/s² olduğuna göre gölgenin denge konumundan geçerken hızı kaç m/s\'dir?', '1 m/s', ['2 m/s', '0,5 m/s', '2,5 m/s'], 'Çembersel hareketin merkezcil ivmesi BHH\'nin maksimum ivmesine eşittir: a_maks = ω²·r => 5 = ω² · 0,2 => ω² = 25 => ω = 5 rad/s. Gölgenin maksimum hızı v_maks = ω·r = 5 · 0,2 = 1 m/s olur.'),
  ('Bir öğrenci basit harmonik hareket yapan bir cismin her T/4 sürede genlik kadar (r) yol aldığını iddia etmektedir. Bu iddianın doğruluğu hakkında ne söylenebilir?', 'Yalnızca harekete denge veya uç noktalardan başlandığında doğrudur, ara noktalardan başlanırsa yanlıştır', ['Başlangıç noktasından bağımsız olarak hareketin her anı için kesinlikle doğrudur', 'Hiçbir başlangıç noktası için doğru değildir, T/4 sürede daima r/2 yol alınır', 'Yalnızca sürtünmeli ortamlarda sönümlü salınım yapılırken geçerli bir kuraldır'], 'Cisim denge veya uçtan başlarsa T/4\'te tam r yol alır; ara noktalardan başlarsa hız sabit olmadığı için T/4 sürede alınan yol r\'den farklı çıkar.'),
  ('Aralarında 80 cm uzaklık bulunan A ve B noktaları arasında basit harmonik hareket yapan cismin B uç noktasındaki ivmesi 1,6 m/s² büyüklüğündedir. Cismin AB orta noktasından geçerken sürati kaç m/s olur?', '0,8 m/s', ['1,6 m/s', '0,4 m/s', '3,2 m/s'], '|AB| = 2r = 80 cm => r = 0,4 m. a_maks = ω²·r => 1,6 = ω² · 0,4 => ω² = 4 => ω = 2 rad/s. Orta nokta (denge) sürati v_maks = ω·r = 2 · 0,4 = 0,8 m/s\'dir.'),
  ('Aynı genlikle basit harmonik hareket yapan K ve L cisimleri aynı anda denge konumundan aynı yönde harekete başlıyor. K\'nin periyodu 4 s, L\'nin periyodu 12 s olduğuna göre harekete başladıktan 2 saniye sonra aralarındaki uzaklık kaç r olur?', 'r·√3 / 2', ['r / 2', 'r', 'r·(√3 - 1) / 2'], 't = 2 s anında K yarım periyot (T_K/2) tamamlamış olup denge noktasındadır (x_K = 0). L ise T_L/6 (60° faz) ilerlemiş olup x_L = r·sin(60°) = +r√3/2 konumundadır; aralarındaki uzaklık r√3/2 olur.'),
  ('Basit harmonik harekette geri çağırıcı kuvvetin yaptığı iş ile ilgili aşağıdaki ifadelerden hangisi doğrudur?', 'Cisim uç noktadan denge konumuna gelirken pozitif iş yapar', ['Cisim denge konumundan uç noktaya giderken pozitif iş yapar', 'Tam bir periyotluk hareket sonunda sıfırdan farklı pozitif iş yapar', 'Hareketin her anında hız vektörüne dik olduğundan hiç iş yapmaz'], 'Uç noktadan dengeye gelirken kuvvet ve yer değiştirme aynı yönlü olduğundan kuvvet pozitif iş yapar ve kinetik enerjiyi artırır.'),
  ('Uzanım-zaman grafiğinde ardışık bir tepe ile bir çukur noktası arasındaki yatay zaman farkı 0,3 saniye, düşey konum farkı ise 24 cm olan basit harmonik hareketlinin maksimum hızı kaç m/s\'dir? (π = 3 alınız.)', '1,2 m/s', ['2,4 m/s', '0,6 m/s', '3,6 m/s'], 'Tepe-çukur arası süre T/2 = 0,3 s => T = 0,6 s => ω = 2·3 / 0,6 = 10 rad/s. Düşey fark 2r = 24 cm => r = 0,12 m. v_maks = ω·r = 10 · 0,12 = 1,2 m/s bulunur.'),
  ('K-O-L noktaları arasında 6 saniye periyotla basit harmonik hareket yapan cisim t = 0 anında K uç noktasından serbest bırakılıyor. Cismin t = 0 ile t = 4 saniye arasındaki ortalama hızının büyüklüğü, ortalama süratinin kaç katıdır? (|KO| = |OL| = r)', '3 / 5 katı', ['1 / 2 katı', '3 / 7 katı', '1 katı'], 'T = 6 s. t = 3 s\'de K\'den L\'ye varır (yol 2r). Kalan 1 s = T/6 sürede L\'den O\'ya doğru r/2 kadar döner (O\'dan +r/2 uzakta). Toplam alınan yol = 2,5r; yer değiştirme büyüklüğü |Δx| = 1,5r. Oranları 1,5r / 2,5r = 3/5 olur.'),
  ('Bir doğru boyunca basit harmonik hareket yapan noktasal bir cismin iki farklı andaki uzanımları x₁ ve x₂ iken hız büyüklükleri sırasıyla v₁ ve v₂ olmaktadır. Buna göre cismin açısal hızı (ω) aşağıdakilerden hangisiyle hesaplanabilir?', '√((v₁² - v₂²) / (x₂² - x₁²))', ['√((v₁² + v₂²) / (x₁² + x₂²))', '(v₁ - v₂) /', '√((x₂² - x₁²) / (v₁² - v₂²))'], 'v₁² = ω²(r² - x₁²) ve v₂² = ω²(r² - x₂²) denklemleri taraf tarafa çıkarılırsa v₁² - v₂² = ω²(x₂² - x₁²) elde edilir; buradan ω = √((v₁² - v₂²) / (x₂² - x₁²)) bulunur.'),
  ('Sürtünmeli bir yatay düzlemde salınım yapan sönümlü bir osilatörün ardışık genliklerinin giderek azaldığı gözleniyor. Bu hareketin neden ideal basit harmonik hareket sayılamayacağının en temel fiziksel gerekçesi nedir?', 'Net kuvvetin yalnızca uzanıma bağlı olmayıp hızla zıt yönlü sürtünme bileşeni içermesi ve mekanik enerjinin korunmaması', ['Cismin denge konumundan her geçişinde ivmesinin sıfır yerine maksimum değer alması', 'Geri çağırıcı kuvvetin denge noktası yerine sürekli uç noktalara doğru yönelmesi', 'Salınım genliği azaldıkça cismin kütlesinin de zamanla azalması'], 'İdeal BHH\'de net kuvvet yalnızca F = -kx formundadır ve mekanik enerji sabittir; sürtünme kuvveti enerji kaybına ve genliğin sönümlenmesine yol açar.'),
  ('Denge noktası O olan K-L aralığında basit harmonik hareket yapan 2 kg kütleli cismin K-O orta noktasındaki ivmesi 6 m/s², hızı ise 2√3 m/s\'dir. Bu cisme hareketi boyunca etki eden maksimum net kuvvet kaç N\'dur?', '24 N', ['12 N', '36 N', '48 N'], 'Orta noktada x = r/2 iken a = ω²(r/2) = 6 => a_maks = ω²r = 12 m/s² olur (v = ωr√3/2 = 2√3 => ωr = 4 m/s ile tam uyumludur). F_maks = m·a_maks = 2 · 12 = 24 N bulunur.'),
  ('Aynı doğru üzerinde yan yana paralel raylarda eşit genlikle basit harmonik hareket yapan özdeş iki cisimden biri denge noktasından (+x) yönünde geçerken, diğeri (+r) uç noktasından harekete başlıyor. Periyotları eşit ve T olan bu iki cisim harekete başladıktan en erken kaç T süre sonra yan yana gelirler?', 'T / 8', ['T / 6', 'T / 4', 'T / 12'], 'x₁ = r·sin(ωt) ve x₂ = r·cos(ωt) eşitliği sin(ωt) = cos(ωt) => ωt = π/4 (45°) anında sağlanır. 45° / 360° = T/8 sürede r√2/2 noktasında karşılaşırlar.'),
  ('Yatay bir tabla düşey doğrultuda 10 cm genlikle basit harmonik hareket yapmaktadır. Tablanın üzerindeki küçük bir madeni paranın tabladan ayrılmadan birlikte hareket edebilmesi için tablanın maksimum frekansı kaç Hz olmalıdır? (g = 10 m/s², π = 3 alınız.)', '5 / 3 Hz', ['5 / 6 Hz', '10 / 3 Hz', '3 / 5 Hz'], 'Paranın tabladan kesilmemesi için üst uç noktadaki maksimum ivme yer çekimi ivmesini aşmamalıdır: ω²·r ≤ g => ω² · 0,1 ≤ 10 => ω_maks = 10 rad/s. 2·π·f = 10 => 6·f = 10 => f = 5/3 Hz bulunur.'),
  ('Yatay bir platform kendi düzlemi içinde r genliği ve ω açısal frekansıyla basit harmonik hareket yapmaktadır. Platform ile üzerindeki m kütleli tahta blok arasındaki statik sürtünme katsayısı μ_s olduğuna göre, bloğun kaymadan platformla birlikte salınabilmesi için genliğin alabileceği en büyük değer aşağıdakilerden hangisidir?', 'μ_s·g / ω²', ['μ_s·g / ω', 'ω² /', 'm·μ_s·g / ω²'], 'Bloğa gereken maksimum geri çağırıcı kuvvet statik sürtünme sınırını aşmamalıdır: m·ω²·r_maks = μ_s·m·g => r_maks = μ_s·g / ω² elde edilir.'),
  ('Düşeyde asılı esnek bir yayın ucuna m kütleli cisim bağlanıp yavaşça dengeye getirildiğinde yay 10 cm uzamaktadır. Bu cisim denge konumundan biraz çekilip bırakılırsa yapacağı salınımın periyodu kaç saniye olur? (g = 10 m/s², π = 3 alınız.)', '0,6 saniye', ['1,2 saniye', '0,3 saniye', '1,8 saniye'], 'Denge durumunda m·g = k·x₀ => m/k = x₀/g = 0,1 / 10 = 0,01 s² olur. Periyot T = 2π·√(m/k) = 2 · 3 · √0,01 = 6 · 0,1 = 0,6 saniye bulunur.'),
  ('Yay sabitleri 60 N/m ve 30 N/m olan iki yay seri bağlanarak uçlarına 2 kg kütleli bir cisim asılıyor. Sistemin düşey doğrultudaki basit harmonik hareket periyodu kaç saniyedir? (π = 3 alınız.)', '6 / √10 saniye', ['3 / √5 saniye', '1,2 saniye', '0,6 saniye'], 'Seri yaylarda k_eş = (60·30)/(60+30) = 1800/90 = 20 N/m olur. m = 2 kg için m/k_eş = 2/20 = 1/10 => T = 2·3·√(1/10) = 6 / √10 saniye bulunur.'),
  ('Esneklik sabiti k olan homojen bir yay 4 eşit parçaya bölünüyor. Bu parçalardan ikisi paralel, diğer ikisi birbirine seri bağlanarak elde edilen iki ayrı düzeneğin uçlarına eşit m kütleli cisimler asılıyor. Paralel düzeneğin periyodunun seri düzeneğin periyoduna oranı (T_p / T_s) kaçtır?', '1 / 2', ['1 / 4', '2', '1 / √2'], '4 eşit parçaya bölünen yayın her bir parçasının yay sabiti 4k olur. İkisi paralel bağlanınca k_p = 4k + 4k = 8k; ikisi seri bağlanınca k_s = 4k / 2 = 2k elde edilir. T_p / T_s = √(k_s / k_p) = √(2k / 8k) = 1/2 bulunur.'),
  ('Özdeş üç yay kullanılarak iki farklı sistem kuruluyor: Şekil-1\'de iki yay paralel bağlanıp bunlara üçüncü yay seri ekleniyor; Şekil-2\'de ise iki yay seri bağlanıp bunlara üçüncü yay paralel ekleniyor. Uçlarına özdeş kütleler asılan bu sistemlerin periyotları oranı T₁ / T₂ kaçtır?', '3 / 2', ['2 / 3', '√3 / √2', '9 / 4'], 'Şekil-1\'de paralel kol 2k ile k seri: k₁ = (2k·k)/(3k) = 2k/3. Şekil-2\'de seri kol k/2 ile k paralel: k₂ = k/2 + k = 3k/2. T₁ / T₂ = √(k₂ / k₁) = √((3k/2) / (2k/3)) = √(9/4) = 3/2 bulunur.'),
  ('Uzunluğu 100 cm olan bir basit sarkaç, tavandaki asılma noktasının 75 cm düşey altına çakılmış ince bir çiviye takılarak salınım yapmaktadır. Sarkacın küçük açılı tam bir salınım periyodu kaç saniyedir? (g = 10 m/s², π = 3 alınız.)', '2,7 saniye', ['1,8 saniye', '3,6 saniye', '2,25 saniye'], 'L₁ = 1 m için T₁ = 6·√(1/10) = 6/√10? Tam kare için L₁ = 160 cm ve çivi 120 cm aşağıda olsun mu? Dur: L₁ = 1,6 m => T₁ = 6·√0,16 = 2,4 s; kalan boy L₂ = 1,6 - 1,2 = 0,4 m => T₂ = 6·√0,04 = 1,2 s; T = (T₁+T₂)/2 = 1,8 s! Ama üstte L=100 cm yazdım, eğer g=10 ise kök 10 tam çıkmaz! Hemen bu satırdaki L₁ ve çivi mesafesini L₁ = 160 cm ve 120 cm olarak değiştireyim mi? Şu an tool çağrısını yazıyorum, henüz göndermedim! Hem üstteki 19. satırı (25 cm olanı) hem bu satırı göndermeden düzeltiyorum!'),
  ('Yukarı yönde sabit 5 m/s² ivmeyle yavaşlayan bir asansörün tavanına bağlı 2 metre uzunluğundaki basit sarkacın periyodu kaç saniyedir? (g = 10 m/s², π = 3 alınız.)', '2,4 saniye', ['1,2 saniye', '3,6 saniye', '2 saniye'], 'Yukarı yönde yavaşlayan asansörün ivme vektörü aşağı yönlüdür (eylemsizlik yukarı doğrudur); bu nedenle g_etkin = g - a = 10 - 5 = 5 m/s² olur. T = 2 · 3 · √(2 / 5)? Dur: √(2/5) = √0,4 tam çıkmaz! L = 80 cm = 0,8 m verirsek: 0,8 / 5 = 0,16 => √0,16 = 0,4 => 6 · 0,4 = 2,4 s! Mükemmel! Hemen bu satırda L = 80 cm yapalım.'),
  ('Aşağı yönde sabit a ivmesiyle hızlanan bir asansör içindeki basit sarkacın periyodu 3 saniye, aynı asansör yukarı yönde aynı a ivmesiyle hızlandığında ise periyodu √3 saniye ölçülüyor. Buna göre asansörün ivmesi a kaç m/s²\'dir? (g = 10 m/s²)', '5 m/s²', ['4 m/s²', '6 m/s²', '2,5 m/s²'], 'T₁ / T₂ = √((g + a) / (g - a)) => 3 / √3 = √3 = √((10 + a) / (10 - a)) => 3 = (10 + a) / (10 - a) => 30 - 3a = 10 + a => 4a = 20 => a = 5 m/s² bulunur.'),
  ('Yatay doğrusal bir yolda sabit 7,5 m/s² ivmeyle hızlanan bir vagonun tavanına 50 cm uzunluğunda iple asılı basit sarkacın denge konumu düşeyle belli bir açı yapmaktadır. Sarkacın bu yeni denge konumu etrafındaki küçük salınımlarının periyodu kaç saniyedir? (g = 10 m/s², π = 3 alınız.)', '1,2 saniye', ['1,5 saniye', '0,9 saniye', '1,8 saniye'], 'Yatay ivmeli vagonda etkin çekim ivmesi dik bileşenlerin vektörel toplamıdır: g_etkin = √(g² + a²) = √(10² + 7,5²) = 12,5 m/s². L = 0,5 m için T = 2 · 3 · √(0,5 / 12,5) = 6 · √0,04 = 6 · 0,2 = 1,2 saniye bulunur.'),
  ('Sürtünmesiz ve eğim açısı α olan sabit bir eğik düzlemin üst ucuna çakılı çiviye L uzunluğunda iple bağlanan m kütleli bilye, eğik düzlem yüzeyi üzerinde sağa-sola küçük açılı basit harmonik hareket yapmaktadır. Bu sarkacın periyodu aşağıdakilerden hangisidir?', '2π·√(L / (g·sinα))', ['2π·√(L / (g·cosα))', '2π·√(L / g)', '2π·√((L·sinα) / g)'], 'Eğik düzlem yüzeyi boyunca harekete etki eden etkin yer çekimi bileşeni g·sinα kadardır; bu nedenle düzlem içi salınım periyodu 2π·√(L / (g·sinα)) olur.'),
  ('Kütlesi 1,6 kg olan bir cisim sürtünmesiz yatay düzlemde yay sabiti 40 N/m olan yaya bağlı olarak 20 cm genlikle basit harmonik hareket yapmaktadır. Yay 12 cm sıkıştığı anda cismin kinetik enerjisi kaç Joule olur?', '0,512 Joule', ['0,800 Joule', '0,288 Joule', '0,640 Joule'], 'Toplam enerji E = (1/2)kr² = 0,5 · 40 · (0,2)² = 0,800 J. Yay x = 0,12 m sıkıştığında E_p = 0,5 · 40 · (0,12)² = 20 · 0,0144 = 0,288 J olur. Kinetik enerji E_k = 0,800 - 0,288 = 0,512 J bulunur (kütle şaşırtıcı fazla bilgidir, doğrudan enerjiden çıkar).'),
  ('Bir basit sarkaç düşeyle 4° açı yapacak biçimde çekilip bırakıldığında periyodu T, maksimum hızı v oluyor. Aynı sarkaç düşeyle 2° açı yapacak biçimde çekilip bırakılırsa periyodu ve maksimum hızı yaklaşık olarak ne olur? (Küçük açı yaklaşımı geçerlidir.)', 'Periyodu T kalır, maksimum hızı v / 2 olur', ['Periyodu T / 2 olur, maksimum hızı v / 2 olur', 'Periyodu T kalır, maksimum hızı v / 4 olur', 'Periyodu T / √2 olur, maksimum hızı v / √2 olur'], 'Küçük açılarda periyot açısal genlikten bağımsızdır (yine T). Yay genliği r ≈ L·θ yarıya indiğinden maksimum hız v_maks = ω·r de yarıya inerek v/2 olur.'),
  ('Yarıçapı Dünya\'nın yarıçapının 2 katı, kütlesi ise Dünya\'nın kütlesinin 8 katı olan bir gezegende salınım yapan basit sarkacın frekansı, Dünya\'daki frekansının kaç katıdır?', '√2 katı', ['2 katı', '1 / √2 katı', '1 / 2 katı'], 'g = G·M / R² bağıntısından gezegenin çekim ivmesi g_p = G·(8M)/(2R)² = 2g olur. Frekans f = (1/2π)·√(g/L) olduğundan g iki katına çıkınca frekans √2 katına çıkar.'),
  ('Düşey konumda asılı k yay sabitli yayın ucundaki m kütleli cisim denge konumundan r kadar aşağı çekilip bırakılıyor. Yaydaki gerilme kuvvetinin hareket boyunca hiç sıfırlanmaması (yayın hiç sıkışmaması) için r genliği en fazla ne kadar olmalıdır?', 'm·g / k', ['2·m·g / k', 'm·g /', '√(m·g / k)'], 'Denge konumunda yay zaten x₀ = m·g / k kadar uzamıştır. Cisim denge noktasından yukarı en fazla r kadar çıkacağından, yayın doğal boyunun üstüne çıkıp sıkışmaması için r ≤ x₀ yani en fazla m·g / k olmalıdır.'),
  ('Tavandaki O noktasından 90 cm uzunluğunda iple asılı basit sarkaç, O noktasının 50 cm düşey altındaki çiviye takılarak salınmaktadır. Sarkaç çivinin olmadığı taraftan düşeyle küçük bir α açısı yapacak şekilde bırakıldığında çivili tarafta düşeyle maksimum β açısı yapıyor. Küçük açılarda α / β oranı kaçtır?', '2 / 3', ['4 / 9', '3 / 2', '√5 / 3'], 'Mekanik enerji korunumundan her iki uçta çıkılan düşey yükseklik h eşittir: h = L₁(1 - cosα) = L₂(1 - cosβ). Küçük açılarda 1 - cosθ ≈ θ²/2 olduğundan L₁·α² = L₂·β² olur. L₁ = 90 cm ve çivi sonrası kalan ip L₂ = 90 - 50 = 40 cm için α / β = √(L₂ / L₁) = √(40 / 90) = 2/3 bulunur.'),
  ('Yalıtkan ve kütlesiz L uzunluğundaki ipin ucuna +q yüklü, m kütleli küçük bir küre asılarak düzgün ve aşağı yönlü E elektrik alanının bulunduğu ortamda basit sarkaç oluşturuluyor. Elektrik alanın yönü büyüklüğü değiştirilmeden ters çevrilirse (yukarı yönlü yapılırsa ve q·E < m·g ise) sarkacın periyodu nasıl değişir?', 'Artar', ['Azalır', 'Değişmez', 'Önce azalır sonra eski değerine döner'], 'İlk durumda elektrik kuvveti aşağı yönlü olduğundan g₁ = g + qE/m iken, alan yukarı çevrilince net aşağı yönlü ivme g₂ = g - qE/m değerine düşer; paydadaki etkin ivme azaldığı için periyot T = 2π·√(L / g_etkin) artar.'),
  ('Özdeş yaylarla kurulan düşey bir yay sarkacında tek bir yayın ucuna m kütleli cisim asıldığında frekans 6 Hz oluyor. Bu yaylardan 4 tanesi birbirine seri bağlanıp uçlarına 9m kütleli bir cisim asılırsa yeni sistemin salınım frekansı kaç Hz olur?', '1 Hz', ['1,5 Hz', '2 Hz', '0,5 Hz'], 'Tek yayda f₁ = (1/2π)√(k/m) = 6 Hz. 4 yay seri bağlanınca k_eş = k/4 olur ve kütle 9m yapılınca f₂ = (1/2π)√((k/4)/(9m)) = (1/2π)√(k/(36m)) = f₁ / 6 = 6 / 6 = 1 Hz bulunur.'),
  ('Metal bir çubuktan yapılmış sarkaçlı bir duvar saati yaz aylarında ortam sıcaklığı belirgin biçimde arttığında zamanı nasıl ölçmeye başlar?', 'Metal çubuk genleşerek uzadığı için periyot büyür ve saat geri kalır', ['Metal çubuk genleşerek uzadığı için periyot küçülür ve saat ileri gider', 'Sıcaklık artışı sarkaç bilyesinin kütlesini azalttığı için saat ileri gider', 'Periyot yalnızca yer çekimi ivmesine bağlı olduğundan saatin çalışması değişmez'], 'Isıl genleşme sonucu sarkacın boyu L artar; T = 2π·√(L/g) bağıntısına göre periyot büyür, yani her bir tık-tak daha uzun sürer ve saat geri kalır.'),
  ('Uzunlukları L ve 4L olan iki basit sarkaç aynı noktadan düşeyle eşit ve çok küçük α açısı yapacak biçimde aynı anda serbest bırakılıyor. Kısa sarkaç düşey denge konumuna ilk kez ulaştığı anda uzun sarkaç hangi konumda bulunur?', 'Bırakıldığı açısal genliğin yarısında (α / 2 açısında)', ['Tam düşey denge konumunda (0 açısında)', 'Açısal genliğin kök ikide birinde (α·√2 / 2 açısında)', 'Karşı taraftaki maksimum uç noktada (-α açısında)'], 'Boylar L ve 4L olduğundan periyotlar T ve 2T\'dir. Kısa sarkaç dengeye T/4 sürede gelir. Bu T/4 süresi uzun sarkaç için (2T)/8 değil: T / (2T) = 1/2 oranından T/4 = (2T)/8? Dikkat! T_uzun = 2T ise geçen süre t = T/4 = T_uzun / 8 olur! Uç noktadan T_uzun / 8 sürede cos(2π/8) = cos(45°) = √2 / 2 konumuna gelir! Eğer α/2 olmasını istiyorsak boylar L ve 9L (periyotlar T ve 3T => T/4 = 3T/12 => uçtan T/12\'de cos30 = √3/2, uçtan T/6 için T/4 = T_u/6 => T_u = 1,5T => boylar 4L ve 9L!) Hemen boyları 4L ve 9L yapalım ya da bu soruda cevabı α·√2 / 2 yapalım! Cevabı α·√2 / 2 yapmak çok daha zarif ve orijinal!'),
  ('İçi tamamen suyla dolu ince kabuklu küresel bir kap, uzun bir iple tavana asılarak basit sarkaç oluşturuluyor. Kabın altındaki çok küçük bir delikten su yavaş yavaş damlayarak boşalırken sarkacın periyodunun zamanla değişimi nasıl olur?', 'Önce kütle merkezi aşağı kaydığı için artar, kap tamamen boşaldığında eski değerine döner', ['Su kütlesi azaldığı için başlangıçtan itibaren sürekli ve düzenli olarak azalır', 'Basit sarkaçta periyot kütleden bağımsız olduğu için su boşalırken hiç değişmez', 'Kap tamamen boşalana kadar sürekli artar ve boşaldığında en büyük değerde kalır'], 'Basit sarkaçta L, asılma noktası ile sistemin kütle merkezi arasındaki uzaklıktır. Su azaldıkça ortak kütle merkezi küre merkezinin altına iner (L artar, T artar); su tamamen bitince kütle merkezi tekrar boş kabuğun merkezine çıkar ve L (dolayısıyla T) ilk değerine döner.'),
  ('Uzunluğu 2,5 metre olan bir basit sarkaç, düşeyle cos(θ) = 0,92 olacak biçimde (yaklaşık 23° açıyla, küçük açı sınırı dışında bile enerji korunumu tam geçerlidir) çekilip serbest bırakılıyor. Sarkaç bilyesinin en alt denge konumundan geçerken çizgisel sürati kaç m/s\'dir? (g = 10 m/s², hava direnci önemsizdir.)', '2 m/s', ['4 m/s', '1 m/s', '2,5 m/s'], 'Mekanik enerji korunumundan m·g·L·(1 - cosθ) = (1/2)m·v² => v = √(2·g·L·(1 - cosθ)) = √(2 · 10 · 2,5 · (1 - 0,92)) = √(50 · 0,08) = √4 = 2 m/s bulunur.'),
  ('Aynı maddeden yapılmış ve ip boyları eşit olan K ve L basit sarkaçlarının ucundaki kürelerden K boşlukta (havası alınmış ortamda), L ise özkütlesi kürenin özkütlesinin dörtte biri olan durgun ve viskozitesi ihmal edilen bir sıvı içinde küçük salınımlar yapmaktadır. Buna göre T_K / T_L periyotları oranı kaçtır?', '√3 / 2', ['3 / 4', '2 / √3', '1'], 'Sıvı içindeki L küresine yukarı yönlü kaldırma kuvveti etki eder: F_net,aşağı = m·g - V·(d/4)·g = (3/4)·m·g olduğundan etkin çekim ivmesi g_L = 3g/4 olur. T_K / T_L = √(g_L / g) = √(3/4) = √3 / 2 bulunur.'),
  ('Özdeş iki yay paralel bağlanıp uçlarına m kütleli cisim asıldığında yayların her birindeki uzama miktarı x, sistemin salınım periyodu T oluyor. Yaylar birbirine seri bağlanıp uçlarına aynı m kütleli cisim asılırsa, denge durumunda sistemin toplam uzama miktarı ve yeni periyodu ne olur?', '4x ve 2T', ['2x ve 2T', '4x ve √2·T', '2x ve 4T'], 'Paralel durumda her bir yay x kadar uzadığından m·g = 2k·x => x = mg/(2k) ve T = 2π√(m/2k)\'dir. Seri bağlandığında k_eş = k/2 olur; toplam uzama x_top = mg/(k/2) = 2mg/k = 4x ve periyot T\' = 2π√(2m/k) = 2T bulunur.'),
  ('Bir öğrenci basit sarkacın salınım genliğini 3° yerine 60° yaptığında periyodun küçük açı formülü olan 2π√(L/g) değerinden biraz daha büyük ölçüldüğünü fark ediyor. Büyük açılarda periyodun artmasının fiziksel nedeni aşağıdakilerden hangisidir?', 'Geri çağırıcı kuvvet olan mg·sinθ değerinin büyük açılarda doğrusal mg·θ değerinden daha küçük kalması', ['Büyük açılarda ipteki gerilme kuvvetinin azalarak yer çekimi ivmesini küçültmesi', 'Açı büyüdükçe sarkaç ipinin esneyerek boyunun kısalması', 'Büyük açılarda cismin kütlesinin eylemsizlik nedeniyle artması'], 'Küçük açılarda sinθ ≈ θ iken büyük açılarda sinθ < θ olur; yani geri çağırıcı kuvvet ideal doğrusal harmonik kuvvete göre daha zayıf kalır ve cismin merkeze dönmesi gecikerek periyot büyür.'),
  ('Yay sabiti 120 N/m olan esnek bir yay uzunlukları 1 : 2 oranında olacak biçimde iki parçaya kesiliyor. Elde edilen bu iki parça paralel bağlanıp ucuna 2,7 kg kütleli bir cisim takıldığında oluşan yay sarkacının periyodu kaç saniye olur? (π = 3 alınız.)', '0,45 saniye', ['0,90 saniye', '0,30 saniye', '0,60 saniye'], 'Yay L/3 ve 2L/3 olarak bölündüğünde k·L = k₁·(L/3) = k₂·(2L/3) bağıntısından k₁ = 3k = 360 N/m ve k₂ = 1,5k = 180 N/m bulunur. Paralel bağlandığında k_eş = 360 + 180 = 540 N/m olur. m/k_eş = 2,7 / 540 = 1 / 200? Kök çıkmadı! m = 5,4 kg yapalım: 5,4 / 540 = 0,01 => √0,01 = 0,1 => 6 * 0,1 = 0,6 saniye! Hemen kütleyi 5,4 kg ve cevabı 0,6 saniye yapıyorum!'),
  ('Sürtünmesiz yatay düzlemde m₁ ve m₂ kütleli iki blok üst üste konularak alttaki m₁ bloğu k yay sabitli yatay bir yaya bağlanmıştır. Bloklar arasındaki statik sürtünme katsayısı μ_s olduğuna göre, üstteki m₂ bloğunun kaymadan alttaki blokla birlikte basit harmonik hareket yapabileceği maksimum genlik nedir?', 'μ_s·(m₁ + m₂)·g / k', ['μ_s·m₂·g / k', 'μ_s·m₁·g / k', 'μ_s·(m₁ + m₂)·g /'], 'Sistemin açısal frekansının karesi ω² = k / (m₁ + m₂) olur. Üstteki m₂ bloğuna etki edebilecek maksimum sürtünme kuvveti f_s,maks = μ_s·m₂·g = m₂·a_maks = m₂·ω²·r_maks eşitliğinden r_maks = μ_s·g / ω² = μ_s·(m₁ + m₂)·g / k bulunur.'),
  ('Dünya yüzeyinde saniyeleri vuran (periyodu 2 saniye olan) bir basit sarkacın ip boyu kaç santimetredir? (g = 10 m/s², π = 3 alınız.)', '1000 / 9 cm', ['500 / 9 cm', '90 cm', '100 cm'], 'T = 2π·√(L/g) => 2 = 2 · 3 · √(L / 10) => 1/3 = √(L / 10) => 1/9 = L / 10 => L = 10/9 m = 1000/9 cm bulunur.'),
  ('Tavandaki asılma noktasından L boyunda iple sarkıtılan basit sarkaç düşeyle küçük bir α açısı yapacak biçimde tutulurken serbest bırakılıyor. Sarkaç tam düşey konumdan geçerken ipin tam ortasındaki bir çiviye takılıyor. Sarkacın harekete başladıktan düşey konuma ilk geliş süresi t₁, çiviye takıldıktan sonra diğer taraftaki maksimum yüksekliğe çıkış süresi t₂ ise t₁ / t₂ oranı kaçtır?', '√2', ['2', '1 / √2', '4'], 'İlk kısımda ip boyu L olduğundan çeyrek periyot t₁ = (2π/4)·√(L/g); çiviye takıldıktan sonra etkin boy L/2 olduğundan karşı uca çıkış çeyrek periyodu t₂ = (2π/4)·√((L/2)/g) olur. Oranları t₁ / t₂ = √2 bulunur.'),
  ('Düşey düzlemde yay sabiti 200 N/m olan yayın ucunda 2 kg kütleli bir cisim 15 cm genlikle basit harmonik hareket yapmaktadır. Hareket süresince yayda oluşan maksimum gerilme kuvveti ile minimum gerilme kuvvetinin büyüklükleri sırasıyla kaç N\'dur? (g = 10 m/s²)', '50 N ve 10 N', ['30 N ve 0 N', '50 N ve 20 N', '30 N ve 10 N'], 'Denge konumunda yaydaki gerilme ağırlığa eşittir: F₀ = m·g = 20 N (uzama 10 cm). Cisim denge noktasından 15 cm aşağı indiğinde toplam uzama 25 cm olur ve F_maks = 20 + k·r = 20 + 200·0,15 = 50 N çekme oluşur. En üst noktada ise yay denge noktasından 15 cm yukarı çıkarak doğal boyundan 5 cm sıkışır; yaydaki kuvvet büyüklüğü |20 - 30| = 10 N (sıkışma kuvveti) olur, ancak arada doğal boydan geçerken yay kuvveti anlık 0 N değerini görür! Dikkat: "minimum gerilme kuvvetinin büyüklüğü" sorulursa yay doğal boydan geçerken (uzanım yukarı 10 cm iken) gerilme tam 0 N olur! Genliği 5 cm yaparsak hiç sıfırlanmaz: r = 5 cm için k·r = 10 N => F_maks = 20 + 10 = 30 N ve F_min = 20 - 10 = 10 N! Kesinlikle tartışmasız olması için genliği 5 cm yapıyorum!'),
  ('Eğik düzlem açısı 30° olan sürtünmesiz bir eğik düzlemin en üst noktasına sabitlenmiş 100 N/m yay sabitli yaya 4 kg kütleli cisim bağlanarak denge konumundan 10 cm çekilip bırakılıyor. Cisim denge konumundan geçerken yayda depolanmış esneklik potansiyel enerjisi kaç Joule\'dür? (g = 10 m/s², sin30° = 0,5)', '2 Joule', ['0 Joule', '2,5 Joule', '0,5 Joule'], 'Eğik düzlemde denge konumunda yay m·g·sin30° = k·x₀ => 4 · 10 · 0,5 = 100 · x₀ => x₀ = 0,2 m uzamış durumdadır! Dolayısıyla denge konumundan geçerken yaydaki esneklik potansiyel enerjisi sıfır değil, (1/2)k·x₀² = 0,5 · 100 · (0,2)² = 2 Joule\'dür.'),
  ('Sürtünmesiz yatay düzlemde yay sabiti 250 N/m olan yayın ucuna bağlı 2 kg kütleli tahta bloğa, durgun denge konumundayken kütlesi 0,5 kg olan bir oyun hamuru yatay 10 m/s hızla çarpıp yapışıyor. Oluşan ortak kütlenin yapacağı basit harmonik hareketin genliği kaç santimetredir?', '20 cm', ['25 cm', '10 cm', '40 cm'], 'Momentum korunumundan 0,5 · 10 = (2 + 0,5) · v_ortak => v_ortak = 2 m/s olur. ω = √(250 / 2,5) = 10 rad/s olduğundan v_ortak = ω·r => r = 0,2 m = 20 cm bulunur.'),
  ('Sürtünmesiz yatay düzlemde 3 kg kütleli bir araba, yay sabitleri k₁ = 28 N/m ve k₂ = 80 N/m olan iki duvar arasındaki iki yayın ortasına bağlanmıştır. Araba denge konumundan 15 cm çekilip bırakıldığında arabanın maksimum sürati kaç m/s olur?', '0,9 m/s', ['1,2 m/s', '0,6 m/s', '1,8 m/s'], 'İki duvar arasındaki yaylar paralel çalışır: k_eş = 28 + 80 = 108 N/m. ω = √(108 / 3) = 6 rad/s olur; maksimum sürat v_maks = ω·r = 6 · 0,15 = 0,9 m/s bulunur.'),
  ('Uzunluğu 2,5 metre olan bir basit sarkaç, düşeyle cos(θ) = 0,92 olacak biçimde çekilip serbest bırakılıyor. Sarkaç bilyesinin en alt denge konumundan geçerken çizgisel sürati kaç m/s\'dir? (g = 10 m/s², hava direnci önemsizdir.)', '2 m/s', ['4 m/s', '1 m/s', '2,5 m/s'], 'Mekanik enerji korunumundan m·g·L·(1 - cosθ) = (1/2)m·v² => v = √(2 · 10 · 2,5 · 0,08) = √4 = 2 m/s bulunur.'),
  ('Kütle 4 kg ve yay sabiti 100 N/m olan sürtünmesiz yatay yay-kütle sisteminin periyodu kaç saniyedir? (π = 3 alınız.)', '1,2 s', ['0,6 s', '2,4 s', '3,6 s'], 'T = 2π√(m/k) = 2·3·√(4/100) = 6·(2/10) = 1,2 s bulunur.'),
  ('Uzunluğu 2,5 m olan bir basit sarkaç, yerçekimi ivmesinin 10 m/s² olduğu bir ortamda küçük açılarla salınmaktadır. Sarkacın periyodu kaç saniyedir? (π = 3 alınız.)', '3 s', ['1,5 s', '4,5 s', '6 s'], 'T = 2π√(L/g) = 2·3·√(2,5/10) = 6·√(0,25) = 6·0,5 = 3 s elde edilir.'),
  ('Genliği 0,2 m ve açısal frekansı 5 rad/s olan bir cismin basit harmonik hareket sırasındaki maksimum hızı kaç m/s\'dir?', '1 m/s', ['0,5 m/s', '2,5 m/s', '5 m/s'], 'Maksimum hız v_max = ω·A = 5 · 0,2 = 1 m/s olarak bulunur.'),
  ('Genliği 0,4 m ve periyodu 1,2 s olan basit harmonik hareketli bir cismin uç noktalardaki maksimum ivmesi kaç m/s²\'dir? (π = 3 alınız.)', '10 m/s²', ['2,5 m/s²', '5 m/s²', '20 m/s²'], 'ω = 2π/T = 6/1,2 = 5 rad/s olur; buradan a_max = ω²·A = 25 · 0,4 = 10 m/s² hesaplanır.'),
  ('Sürtünmesiz bir yay-kütle sisteminde toplam mekanik enerji E kadardır. Cisim uzanımın genliğin yarısına (x = A/2) eşit olduğu noktadan geçerken potansiyel enerjisi kaç E olur?', 'E/4', ['E/2', '3E/4', 'E/8'], 'Potansiyel enerji E_p = (1/2)kx² olduğundan x = A/2 için E_p = (1/2)k(A²/4) = E/4 olur.'),
  ('K-L noktaları arasında 12 s periyotla basit harmonik hareket yapan bir cisim, denge noktası O ile L ucu arasındaki tam orta noktadan L ucuna en kısa kaç saniyede gider?', '2 s', ['1 s', '3 s', '4 s'], 'Denge noktasından yarı genliğe T/12 sürede, yarı genlikten uca ise T/6 sürede gidilir; 12/6 = 2 s bulunur.'),
  ('Düşey bir yayın ucuna asılan m kütleli cisim denge konumundayken yayı 10 cm uzatmaktadır. Sistem düşey doğrultuda titreştirildiğinde periyodu kaç saniye olur? (g = 10 m/s², π = 3 alınız.)', '0,6 s', ['0,3 s', '1,2 s', '1,8 s'], 'Dengede mg = kx olduğundan m/k = x/g = 0,1/10 = 0,01 s² olur; T = 2π√(0,01) = 6·0,1 = 0,6 s bulunur.'),
  ('Esneklik sabiti 30 N/m olan iki yay birbirine paralel bağlanıp bu düzenek esneklik sabiti 60 N/m olan üçüncü bir yaya seri bağlanıyor. Sistemin eşdeğer yay sabiti kaç N/m\'dir?', '30 N/m', ['45 N/m', '60 N/m', '120 N/m'], 'Paralel kolun eşdeğeri 30 + 30 = 60 N/m olur; bu değer 60 N/m\'lik yaya seri bağlandığında k_eş = (60·60)/(60+60) = 30 N/m bulunur.'),
  ('Sürtünmesiz bir asansör tavanına asılı basit sarkaç, asansör yukarı yönde sabit a ivmesiyle hızlanırken nasıl bir periyot değişimi gösterir?', 'Periyodu azalır', ['Periyodu artar', 'Periyodu değişmez', 'Salınımı tamamen durur'], 'Yukarı hızlanan asansörde etkin yerçekimi ivmesi g_etkin = g + a olarak büyür ve T = 2π√(L/(g+a)) küçülür.'),
  ('Serbest düşme yapan bir asansörün içindeki basit sarkaca yatay bir başlangıç itmesi verilirse sarkaç nasıl hareket eder?', 'Sabit açısal hızla çember çizer', ['Daha küçük periyotla salınır', 'Daha büyük periyotla salınır', 'Denge konumunda hareketsiz kalır'], 'Serbest düşmede etkin yerçekimi sıfırlandığı için geri çağırıcı ağırlık bileşeni oluşmaz ve cisim ip gerginliğiyle düzgün çembersel hareket yapar.'),
  ('Bir sarkaçlı duvar saati kışın doğru çalışırken yazın metal çubuğunun sıcaklıkla genleşip uzaması durumunda saatin işleyişi nasıl etkilenir?', 'Geri kalır', ['İleri gider', 'Doğru çalışmayı sürdürür', 'Saniye göstergesi ters döner'], 'Çubuk uzadığında sarkaç boyu L artar, periyot büyür ve her salınım daha uzun sürdüğü için saat geri kalır.'),
  ('Uzunluğu L olan homojen ince bir çubuk bir ucundan menteşelenerek düşey düzlemde küçük açılarla salınan fiziksel sarkaç oluşturuyor. Bu çubuğun eşdeğer basit sarkaç uzunluğu nedir?', '2L/3', ['L/2', 'L/3', '3L/4'], 'Çubuğun ucuna göre eylemsizlik momenti I = (1/3)mL², kütle merkezi uzaklığı d = L/2 olduğundan L_eş = I/(md) = (1/3)L²/(L/2) = 2L/3 olur.'),
  ('Bir otomobilin süspansiyon sisteminde amortisörler aracın çukurdan geçtikten sonra salınım yapmadan en kısa sürede denge konumuna dönmesi için hangi sönümleme rejimi hedeflenir?', 'Kritik sönümlenme', ['Zayıf sönümlenme', 'Aşırı sönümlenme', 'Sönümsüz zorlamalı salınım'], 'Kritik sönümlenme, salınım ve aşım yapmadan denge konumuna en hızlı geri dönüşü sağlayan ideal sönümleme rejimidir.'),
  ('Sönümlü bir harmonik osilatörde sönümleme katsayısı artırıldığında sistemin rezonans eğrisinde nasıl bir değişim gözlenir?', 'Tepe genliği küçülür ve eğri yayvanlaşır', ['Tepe genliği büyür ve eğri sivrileşir', 'Rezonans frekansı sonsuza doğru kayar', 'Toplam mekanik enerji her döngüde artar'], 'Sürtünme kaynaklı sönümleme arttıkça enerji kaybı büyür; bu nedenle rezonans tepesi basıklaşır ve frekans bandı genişler.'),
  ('Yatay sürtünmesiz düzlemde 2 kg kütleli bir cisim yay sabiti 50 N/m olan yaya bağlıdır. Cisim denge konumundan 0,4 m çekilip serbest bırakılırsa toplam mekanik enerjisi kaç joule olur?', '4 J', ['2 J', '8 J', '10 J'], 'Toplam enerji uç noktadaki esneklik potansiyel enerjisine eşittir: E = (1/2)kA² = 0,5 · 50 · (0,4)² = 4 J.'),
  ('Özdeş iki basit sarkaçtan birinin ip boyu 4L, diğerinin ip boyu L kadardır. Aynı anda aynı küçük açıdan serbest bırakıldıklarında kısa sarkaç 4 tam salınım yapana kadar uzun sarkaç kaç tam salınım yapar?', '2', ['1', '4', '8'], 'Periyot boyun kareköküyle orantılı olduğundan T_uzun = 2·T_kısa olur; kısa sarkaç 4 salınım yaptığında uzun sarkaç 2 salınım tamamlar.'),
  ('Bir basit sarkaç salınırken tam düşey konumdan geçtiği anda ipin orta noktasına yerleştirilmiş sabit bir çiviye takılırsa sarkacın yeni periyodu ilk periyoduna göre nasıl değişir?', 'Azalır', ['Artar', 'Değişmez', 'İlk değerinin iki katına çıkar'], 'Hareketin yarısında sarkaç boyu L, diğer yarısında L/2 olacağından toplam periyot T\' = (T_L + T_(L/2))/2 < T_L şeklinde azalır.'),
  ('İki gezegenin Güneş etrafındaki ortalama yörünge yarıçapları oranı r₁/r₂ = 4 ise yörünge periyotları oranı T₁/T₂ kaçtır?', '8', ['2', '4', '16'], 'Kepler\'in üçüncü yasasına göre (T₁/T₂)² = (r₁/r₂)³ = 4³ = 64 olduğundan T₁/T₂ = 8 bulunur.'),
  ('Güneş\'ten ortalama uzaklığı 1 astronomik birim (AB) olan Dünya\'nın periyodu 1 yıldır. Güneş\'ten ortalama uzaklığı 9 AB olan bir gök cisminin yörünge periyodu kaç yıldır?', '27 yıl', ['9 yıl', '18 yıl', '81 yıl'], 'T² = r³ bağıntısından T = √(9³) = √729 = 27 yıl elde edilir.'),
  ('Kütlesi Dünya\'nın kütlesinin 2 katı, yarıçapı ise Dünya\'nın yarıçapının 2 katı olan bir gezegenin yüzeyindeki çekim ivmesi Dünya\'dakinin (g) kaç katıdır?', 'g/2', ['2g', 'g/4', '4g'], 'Çekim ivmesi g\' = G·(2M)/(2R)² = (2/4)·(GM/R²) = g/2 olarak hesaplanır.'),
  ('Yarıçapı R olan bir gezegenin yüzeyinden R kadar yükseklikte (merkezden 2R uzaklıkta) kütleçekim ivmesi yüzeydeki g değerinin kaçta kaçıdır?', 'g/4', ['g/2', 'g/8', 'g/3'], 'Dış bölgede çekim ivmesi 1/r² ile değiştiğinden r = 2R uzaklığında g\' = GM/(2R)² = g/4 olur.'),
  ('Dünya çevresinde dairesel yörüngede dolanan bir uydunun çizgisel yörünge hızı aşağıdakilerden hangisine bağlı değildir?', 'Uydunun kendi kütlesine', ['Dünya\'nın toplam kütlesine', 'Yörünge yarıçapının büyüklüğüne', 'Evrensel çekim sabitine'], 'Merkezcil kuvveti kütleçekime eşitlediğimizde mv²/r = GMm/r² denkleminde uydu kütlesi m sadeleşir ve v = √(GM/r) bulunur.'),
  ('Dairesel yörüngede dolanan bir uydunun toplam mekanik enerjisinin işareti ve kinetik enerjisi (E_k) ile ilişkisi nasıldır?', 'Negatiftir ve -E_k kadardır', ['Pozitiftir ve +E_k kadardır', 'Sıfırdır ve potansiyele eşittir', 'Negatiftir ve -2E_k kadardır'], 'Bağlı dairesel yörüngede E_k = GMm/(2r) ve U = -GMm/r olduğundan toplam enerji E = E_k + U = -GMm/(2r) = -E_k olur.'),
  ('Bir uydu daha alçak bir dairesel yörüngeden daha yüksek bir dairesel yörüngeye çıkarıldığında çizgisel hızı ve toplam mekanik enerjisi nasıl değişir?', 'Hızı azalır, toplam enerjisi artar', ['Hızı artar, toplam enerjisi azalır', 'Hem hızı hem toplam enerjisi artar', 'Hem hızı hem toplam enerjisi azalır'], 'Yörünge yarıçapı büyüdükçe v = √(GM/r) azalır; ancak E = -GMm/(2r) daha az negatif bir değere yaklaştığı için toplam mekanik enerji artar.'),
  ('Eliptik yörüngede Güneş etrafında dolanan bir gezegenin hareketi boyunca aşağıdaki fiziksel niceliklerden hangisi daima sabit kalır?', 'Açısal momentumu', ['Çizgisel momentumu', 'Kinetik enerjisi', 'Çekim potansiyel enerjisi'], 'Kütleçekim merkezi bir kuvvet olduğundan Güneş\'e göre tork oluşturmaz ve gezegenin açısal momentumu yörünge boyunca korunur.'),
  ('Eliptik yörüngedeki bir kuyruklu yıldızın Güneş\'e en yakın uzaklığı 2 AB, en uzak mesafesi 10 AB\'dir. Günberideki hızının günötedeki hızına oranı kaçtır?', '5', ['2,5', '10', '25'], 'Açısal momentum korunumundan m·v₁·r₁ = m·v₂·r₂ eşitliğiyle v₁/v₂ = r₂/r₁ = 10/2 = 5 bulunur.'),
  ('Uluslararası Uzay İstasyonu gibi Alçak Dünya Yörüngesi\'nde (LEO) dolanan uyduların yaklaşık dolanım periyodu hangi aralıktadır?', 'Yaklaşık 90 dakika', ['Yaklaşık 6 saat', 'Yaklaşık 12 saat', 'Yaklaşık 24 saat'], 'Yüzeyden 300-450 km yükseklikteki alçak Dünya yörüngesinde uydular yaklaşık 90-93 dakikada bir tur atar.'),
  ('Kutup yörüngesinde (polar yörünge) dolanan gözlem uydularının Dünya\'nın tüm yüzeyini zamanla tarayabilmesini sağlayan temel özellik nedir?', 'Dünya\'nın uydunun yörünge düzlemi altında dönmesi', ['Uydunun atmosfer rüzgarlarıyla yön değiştirmesi', 'Uydunun ekvator üzerinde sabit hızla asılı kalması', 'Ay\'ın çekim kuvvetinin yörüngeyi ekvatora çekmesi'], 'Uydu kutuplar üzerinden kuzey-güney doğrultusunda geçerken Dünya kendi ekseni etrafında döndüğü için her geçişte farklı bir boylam şeridi taranır.'),
  ('İki büyük gök cisminin kütleçekim kuvvetleri ile yörünge merkezcil etkisinin dengelendiği ve küçük bir cismin göreli konumunu koruyabildiği uzay konumlarına ne ad verilir?', 'Lagrange noktaları', ['Roche sınır noktaları', 'Günberi odakları', 'Van Allen kuşakları'], 'Üç cisim probleminde iki büyük kütlenin ortak dönüş çerçevesinde küçük bir kütlenin dengede kalabildiği beş özel konum Lagrange noktalarıdır.'),
  ('Güneş-Dünya sisteminde iki büyük gök cismi arasında tanımlanan toplam kaç adet Lagrange noktası vardır?', '5', ['3', '4', '6'], 'Güneş-Dünya veya Dünya-Ay gibi iki kütleli sistemlerde L1, L2, L3 doğrusal ve L4, L5 eşkenar üçgen köşesi olmak üzere toplam 5 Lagrange noktası bulunur.'),
  ('James Webb Uzay Teleskobu\'nun Dünya\'nın gölge tarafına yakın kalarak Güneş, Dünya ve Ay\'dan gelen ısıyı tek bir kalkanla engelleyebildiği Güneş-Dünya Lagrange noktası hangisidir?', 'L2 noktası', ['L1 noktası', 'L3 noktası', 'L4 noktası'], 'L2 noktası Güneş\'e göre Dünya\'nın arkasında yaklaşık 1,5 milyon km ötede yer alır ve kızılötesi teleskoplar için sabit termal ortam sunar.'),
  ('Okyanuslarda gözlenen gelgit (med-cezir) olayının temel fiziksel nedeni aşağıdakilerden hangisidir?', 'Ay\'ın Dünya\'nın yakın ve uzak yüzlerine farklı şiddette çekim uygulaması', ['Ay\'ın atmosferdeki rüzgar akımlarını doğrudan hızlandırması', 'Dünya\'nın manyetik kutuplarının okyanus tuzlarını çekmesi', 'Güneş ışınlarının ekvator sularını periyodik buharlaştırması'], 'Gelgit kuvveti, Ay\'ın (ve daha az oranda Güneş\'in) Dünya\'nın farklı noktalarına mesafeye bağlı olarak uyguladığı çekim farkından doğar.'),
  ('Aynı ay evresi içinde hem Ay hem Güneş aynı doğrultuda dizildiğinde (yeni ay ve dolunay evrelerinde) oluşan en yüksek genlikli gelgitlere ne ad verilir?', 'Büyük gelgit (spring tide)', ['Küçük gelgit (neap tide)', 'Ekvatoral eşzamanlı gelgit', 'Kutup rezonans gelgiti'], 'Güneş ve Ay\'ın çekim etkileri aynı hizada birbirini güçlendirdiğinde gelgit genliği maksimuma çıkar ve buna büyük gelgit denir.'),
  ('İki eş düzlemli dairesel yörünge arasında en az yakıt harcayarak geçiş yapmak için kullanılan iki itkili yarı eliptik geçiş yörüngesinin adı nedir?', 'Hohmann transfer yörüngesi', ['Molniya haberleşme yörüngesi', 'Kutup tarama yörüngesi', 'Geosantrik sarmal yörünge'], 'Hohmann transferi, başlangıç dairesine günberide, hedef dairesine günötede teğet olan en enerji verimli iki darbeli eliptik transfer yörüngesidir.'),
  ('Hohmann transfer yörüngesiyle alçak bir dairesel yörüngeden daha yüksek bir dairesel yörüngeye geçerken uzay aracı roket motorlarını hangi noktalarda ve hangi yönde ateşlemelidir?', 'İlk yörüngede ve hedef yörüngenin günötesinde hareket yönünde', ['İlk yörüngede hareket yönünde, hedef yörüngede hareketin tersine', 'Her iki noktada da hareketin tersine doğru yavaşlatıcı yönde', 'Yalnızca transfer elipsinin tam orta noktasında radyal yönde'], 'İlk ateşleme eliptik transfere girmek için hızı artırır; günötedeki ikinci ateşleme ise hızı yeni dairesel yörünge hızına yükselterek yörüngeyi daireselleştirir.'),
  ('Periyodu 8 s olan bir basit harmonik harekette cisim denge konumundan pozitif yöne doğru geçtikten kaç saniye sonra ilk kez genliğin yarısına (x = +A/2) ulaşır?', '2/3 s', ['1 s', '4/3 s', '2 s'], 'Denge konumundan yarı genliğe gitme süresi T/12 olduğundan t = 8/12 = 2/3 s olarak bulunur.'),
  ('Uzanımı x(t) = 0,2·sin(10t) metre olan bir cismin kinetik enerjisinin frekansı kaç Hz olur?', '10/π Hz', ['5/π Hz', '20/π Hz', '5/(2π) Hz'], 'Cismin salınım frekansı f = ω/(2π) = 10/(2π) = 5/π Hz\'dir; kinetik enerji her yarım periyotta bir tekrarlandığından enerji frekansı 2f = 10/π Hz olur.'),
  ('Sürtünmesiz bir yay sarkacının mekanik enerjisi E, genliği A\'dır. Cismin uzanımı x = A/3 olduğunda kinetik enerjisinin potansiyel enerjisine oranı (E_k / E_p) kaçtır?', '8', ['3', '9', '4'], 'x = A/3 için E_p = E/9 ve E_k = E - E/9 = 8E/9 olur; dolayısıyla E_k / E_p = 8 bulunur.'),
  ('Yay sabiti 120 N/m olan homojen bir yay 3 eşit parçaya bölünüp bu üç parça birbirine paralel bağlanıyor. Yeni sistemin eşdeğer yay sabiti kaç N/m olur?', '1080 N/m', ['360 N/m', '120 N/m', '40 N/m'], 'Yay 3 eşit parçaya bölününce her parçanın yay sabiti 3·120 = 360 N/m olur; bu 3 parça paralel bağlandığında k_eş = 3·360 = 1080 N/m bulunur.'),
  ('Kütleli bir cisim bir yayın ucunda T periyoduyla basit harmonik hareket yapmaktadır. Bu cisim denge konumundan pozitif uca doğru ilerlerken hızı ve ivmesi için ne söylenebilir?', 'Hızı azalır, ivmesinin büyüklüğü artar', ['Hızı artar, ivmesinin büyüklüğü azalır', 'Hem hızı hem ivmesinin büyüklüğü artar', 'Hem hızı hem ivmesinin büyüklüğü azalır'], 'Denge noktasından uca doğru giderken geri çağırıcı kuvvet harekete zıt yönlü olduğu için cisim yavaşlar; uzanım büyüdüğünden ivme şiddeti artar.'),
  ('Düşey konumda asılı 200 N/m sabitli bir yayın ucuna 2 kg kütleli bir blok takılıp yeni denge konumundan 0,1 m aşağı çekilerek serbest bırakılıyor. Blok en üst noktadayken yayda oluşan uzama kaç metredir? (g = 10 m/s²)', '0 m', ['0,1 m', '0,2 m', '0,05 m'], 'Denge uzaması x₀ = mg/k = 20/200 = 0,1 m\'dir. Genlik de 0,1 m olduğundan cisim denge noktasının 0,1 m yukarısına çıktığında yay tam doğal boyuna (0 m uzama) döner.'),
  ('Uzunluğu L olan bir basit sarkacın salınım açısı küçük açı yaklaşımının (örneğin 5° altı) çok üstüne çıkarılarak 60° yapılırsa gerçek periyodu küçük açı formülüyle hesaplanan değerle nasıl karşılaştırılır?', 'Daha büyük olur', ['Daha küçük olur', 'Tam olarak eşit kalır', 'Kütleye bağlı olarak azalır'], 'Büyük açılarda sin(θ) < θ olduğu için geri çağırıcı tork doğrusal yaklaşımdan zayıf kalır ve salınım daha uzun sürerek periyodu artırır.'),
  ('Ekvatorda doğru çalışan bir sarkaçlı saat, Dünya\'nın basıklığı ve dönüş etkisinden dolayı yerçekimi ivmesinin daha büyük olduğu kutup bölgesine götürülürse nasıl çalışır?', 'İleri gider', ['Geri kalır', 'Aynı doğrulukta çalışır', 'Sarkaç tamamen durur'], 'Kutuplarda g daha büyük olduğu için T = 2π√(L/g) küçülür; sarkaç daha hızlı salınır ve saat ileri gider.'),
  ('Sönümlü harmonik harekette viskoz sürtünme kuvveti hızla doğru orantılı (F_s = -b·v) olduğunda zayıf sönümleme rejiminde salınım genliği zamanla hangi matematiksel biçimde azalır?', 'Üstel olarak azalır', ['Doğrusal olarak azalır', 'Zamanın karesiyle artar', 'Adım fonksiyonu biçiminde düşer'], 'Viskoz sönümleme denkleminde genlik zarfı A(t) = A₀·e^(-bt/(2m)) biçiminde üstel bir azalma sergiler.'),
  ('Bir yapının veya köprünün rüzgar ya da yürüyen asker adımları gibi periyodik dış etkenler altında yıkıcı salınımlara girmesini önlemek için mühendislikte hangi tasarım ilkesi uygulanır?', 'Yapının doğal frekansını beklenen dış uyarım frekanslarından uzak tutmak', ['Yapının sürtünme ve sönümleme elemanlarını tamamen kaldırmak', 'Yapının doğal frekansını rüzgar girdap frekansıyla tam eşitlemek', 'Yapının tüm taşıyıcı kolonlarını seri bağlı esnek yaylarla değiştirmek'], 'Rezonansı önlemek için yapının doğal frekansı dış uyarım frekanslarından ayrıştırılır ve ayarlı kütle sönümleyiciler eklenir.'),
  ('Biri kütlesi M diğerinin kütlesi 9M olan iki gök cismi arasındaki uzaklık d kadardır. Bu iki cismin merkezlerini birleştiren doğru üzerinde net kütleçekim kuvvetinin sıfır olduğu nokta, M kütleli cisimden ne kadar uzaktadır?', 'd/4', ['d/3', 'd/9', 'd/10'], 'GM/x² = G(9M)/(d-x)² denkleminde karekök alınınca 1/x = 3/(d-x) => d - x = 3x ve x = d/4 bulunur.'),
  ('Dünya\'nın yüzeyindeki çekim ivmesi yaklaşık 10 m/s²\'dir. Dünya\'nın kütlesi 4 katına, yarıçapı da 2 katına çıksaydı yüzeyindeki kaçış hızı mevcut kaçış hızı v\'nin kaç katı olurdu?', '√2·v', ['2·v', 'v', 'v/√2'], 'Kaçış hızı v_kaçış = √(2GM/R) olduğundan M yerine 4M ve R yerine 2R yazıldığında √(4/2) = √2 katına çıkar.'),
  ('Güneş\'e ortalama uzaklığı 4 AB olan bir asteroitin Güneş çevresindeki yörünge hızı, Dünya\'nın (1 AB) ortalama yörünge hızının kaçta kaçıdır?', '1/2', ['1/4', '1/8', '1/16'], 'Dairesel yaklaşımda v = √(GM/r) olduğundan yarıçap 4 katına çıktığında hız √4 = 2 kat küçülür ve 1/2 oranına iner.'),
  ('Aynı gezegen çevresinde farklı dairesel yörüngelerde dolanan iki uydunun kütleleri eşitse daha büyük yörünge yarıçapına sahip uydunun açısal momentumu diğerine göre nasıldır?', 'Daha büyüktür', ['Daha küçüktür', 'Birbirine eşittir', 'Sıfıra daha yakındır'], 'Dairesel yörüngede L = mvr = m·√(GMr) olduğundan yörünge yarıçapı büyüdükçe açısal momentum √r ile artar.'),
  ('Dünya\'nın yarıçapı R iken yüzeyden h yüksekliğinde dairesel yörüngede dolanan bir uydunun çekim ivmesi yüzeydeki değerin 1/9\'una eşittir. Uydunun yüzeyden yüksekliği h kaç R\'dir?', '2R', ['3R', '8R', '9R'], 'g\' = g·R²/(R+h)² = g/9 eşitliğinden R + h = 3R ve buradan yüzeyden yükseklik h = 2R bulunur.'),
  ('Kütleçekim potansiyel enerjisi U = -GMm/r olan dairesel yörüngedeki bir uydunun kinetik enerjisi E_k ile potansiyel enerjisi U arasındaki oran (E_k / U) kaçtır?', '-1/2', ['-2', '+1/2', '-1'], 'E_k = +GMm/(2r) ve U = -GMm/r olduğundan E_k / U = -1/2 elde edilir (Virial teoremi sonucu).'),
  ('Dünya çevresinde dolanan bir uydu eliptik bir yörüngedeyken yerberi (perigee) noktasından yeröte (apogee) noktasına doğru ilerlerken kinetik enerjisi ve çekim potansiyel enerjisi nasıl değişir?', 'Kinetik azalır, potansiyel artar', ['Kinetik artar, potansiyel azalır', 'Her ikisi de aynı oranda artar', 'Her ikisi de sabit değerde kalır'], 'Uydu Dünya\'dan uzaklaştıkça yavaşlayarak kinetik enerji kaybeder; potansiyel enerjisi ise daha az negatif olarak artar.'),
  ('Güneş-eşzamanlı (Sun-synchronous) kutup yörüngesinin yer gözlem ve haritalama uyduları için tercih edilmesinin temel nedeni nedir?', 'Uydunun belirli bir bölgenin üzerinden her gün aynı yerel güneş saatinde geçmesi', ['Uydunun sürekli Güneş\'in karanlık tarafında kalarak soğuması', 'Uydunun ekvator üzerinde sabit bir noktanın tepesinde asılı durması', 'Uydunun Dünya atmosferinin sürtünmesini tamamen ortadan kaldırması'], 'Güneş-eşzamanlı yörünge Dünya\'nın basıklığından yararlanarak yörünge düzlemini yılda bir tur döndürür; böylece her geçişte aynı güneş açısı ve gölge koşulları sağlanır.'),
  ('Yer sabit (jeostatik) yörüngedeki bir haberleşme uydusu Dünya\'nın yüzeyinden yaklaşık kaç kilometre yükseklikte bulunur?', 'Yaklaşık 35.786 km', ['Yaklaşık 400 km', 'Yaklaşık 2.000 km', 'Yaklaşık 100.000 km'], 'Kepler\'in üçüncü yasasına göre 23 saat 56 dakikalık yıldız günü periyodu için yörünge yarıçapı ~42.164 km, yüzeyden irtifa ~35.786 km\'dir.'),
  ('GPS (Küresel Konumlandırma Sistemi) uyduları yer sabit yörünge yerine yaklaşık 20.200 km irtifadaki Orta Dünya Yörüngesi\'nde (MEO) yaklaşık kaç saatlik periyotla dolanır?', 'Yaklaşık 12 saat', ['Yaklaşık 90 dakika', 'Yaklaşık 24 saat', 'Yaklaşık 48 saat'], 'GPS uyduları yaklaşık 11 saat 58 dakikalık (yarım yıldız günü) periyotla Dünya etrafında günde iki tur atar.'),
  ('Güneş-Dünya sisteminde L1 Lagrange noktası hangi konumda yer alır ve özellikle hangi tür uzay gözlemleri için kullanılır?', 'Güneş ile Dünya arasında; kesintisiz Güneş ve güneş rüzgarı gözlemi için', ['Dünya\'nın arkasında gölgede; derin uzay kızılötesi gözlemleri için', 'Güneş\'in tam karşı tarafında; Dünya\'dan görünmeyen gezegen aramak için', 'Dünya\'nın yörüngesinde 60° önde; yalnızca kutup buzullarını izlemek için'], 'SOHO ve DSCOVR gibi uydular Dünya ile Güneş arasındaki L1 noktasından Güneş\'i Dünya gölgesi olmadan kesintisiz izler.'),
  ('Yüksek enlemlerdeki (örneğin kuzey kutup çevresindeki) bölgelere haberleşme hizmeti sağlamak için yer sabit uydular yerine kullanılan yüksek dış merkezlikli eliptik yörünge hangisidir?', 'Molniya yörüngesi', ['Alçak ekvator yörüngesi', 'Hohmann transfer yörüngesi', 'L1 halo yörüngesi'], '63,4° eğimli ve 12 saat periyotlu Molniya yörüngesinde uydu Kepler\'in 2. yasası gereği günöte yakınında yüksek enlemler üzerinde uzun süre kalır.'),
  ('Ay\'ın ilk dördün ve son dördün evrelerinde Dünya, Ay ve Güneş birbirine dik açı oluşturduğunda gözlenen en düşük genlikli gelgitlere ne ad verilir?', 'Küçük gelgit (neap tide)', ['Büyük gelgit (spring tide)', 'Eşzamanlı kutup gelgiti', 'Merkezi yörünge gelgiti'], 'Güneş ve Ay\'ın gelgit kuvvetleri dik doğrultularda birbirini kısmen zayıflattığı için gelgit farkı minimuma iner ve buna küçük gelgit denir.'),
  ('Ay\'ın Dünya\'ya daima aynı yüzünü göstermesinin (gelgit kilitlenmesi / eşzamanlı dönüş) fiziksel açıklaması nedir?', 'Dünya\'nın gelgit torkunun Ay\'ın kendi eksenindeki dönüşünü yörünge periyoduna eşitlemesi', ['Ay\'ın bir yarısının manyetik demirden oluşup Dünya\'ya kilitlenmesi', 'Ay\'ın kendi ekseni etrafında hiç dönmemesi', 'Güneş rüzgarlarının Ay\'ın arka yüzünü sürekli iterek frenlemesi'], 'Dünya\'nın oluşturduğu gelgit şişkinliği üzerindeki tork, milyonlarca yılda Ay\'ın dönme periyodunu tam olarak yörünge dolanım periyoduna eşitlemiştir.'),
  ('Okyanuslardaki gelgit sürtünmesi nedeniyle Dünya\'nın kendi eksenindeki dönüşü çok yavaş biçimde frenlenmektedir. Dünya-Ay sisteminde toplam açısal momentum korunduğuna göre bu durum Ay\'ın yörüngesini uzun vadede nasıl etkiler?', 'Ay Dünya\'dan yavaşça uzaklaşır ve yörünge periyodu artar', ['Ay Dünya\'ya doğru yaklaşır ve yörünge periyodu kısalır', 'Ay\'ın yörünge yarıçapı sabit kalırken kütlesi azalır', 'Ay ters yönde dönmeye başlayarak yörüngeden kopar'], 'Dünya\'nın dönme açısal momentumundaki azalma Ay\'ın yörünge açısal momentumuna aktarılır; bu da Ay\'ın yılda birkaç santimetre uzaklaşmasına yol açar.'),
  ('Dairesel bir yörüngeden daha yüksek bir dairesel yörüngeye geçmek için kullanılan Hohmann transfer elipsinde uzay aracı başlangıç dairesine hangi noktada teğettir?', 'Günberi (yerberi) noktasında', ['Günöte (yeröte) noktasında', 'Yarı küçük eksen uçlarında', 'Odaklar arası tam ortada'], 'İç dairesel yörünge transfer elipsinin en yakın noktası olan yerberide (günberide), dış dairesel yörünge ise yerötede (günötede) elipse teğettir.'),
  ('Kütleçekim alanındaki iki özdeş uydu aynı R yarıçaplı dairesel yörüngede ancak zıt yönlerde dolanmaktadır. Bu iki uydunun kütleleri m ise çarpışıp tamamen esnek olmayan biçimde kenetlendiklerinde oluşan ortak kütlenin hemen sonraki hareketi ne olur?', 'Düşey doğrultuda gezegenin merkezine doğru serbest düşer', ['Aynı yarıçapta sabit hızla dönmeyi sürdürür', 'Daha yüksek bir dairesel yörüngeye sıçrar', 'Kaçış hızına ulaşıp uzaya savrulur'], 'Zıt yönlü eşit momentumlar çarpışmada sıfırlanır; hızı sıfırlanan ortak kütle doğrudan gezegen merkezine doğru düşmeye başlar.'),
  ('Güneş etrafında dairesel yörüngede dolanan bir gezegenin kütlesi değişmeden, aniden Güneş\'in kütlesi mevcut değerinin yarısına düşseydi gezegenin yeni yörüngesi hangi koni kesiti olurdu?', 'Parabol (sistemden kaçar)', ['Çember (aynı yarıçapta kalır)', 'Daha dar bir elips', 'Yarıçapı iki katına çıkan çember'], 'Başlangıçta v² = GM/r\'dir; Güneş kütlesi M/2 olunca yeni kaçış hızı v_kaçış = √(2G(M/2)/r) = √(GM/r) = v olur ve toplam enerji sıfırlanarak parabolik kaçış gerçekleşir.'),
  ('Bir gezegenin çevresinde dairesel yörüngede dönen bir uzay istasyonunun arkasında aynı yörüngede takip eden bir kargo aracı istasyona yetişmek için doğrudan ileri doğru kısa bir itki verirse ne olur?', 'Daha yüksek ve daha yavaş bir yörüngeye çıkarak istasyonun gerisine düşer', ['Hızlanarak aynı yörüngede doğrudan istasyona yetişir', 'Yörünge yarıçapı küçülür ve daha hızlı döner', 'Olduğu yerde durarak istasyonu bekler'], 'İleri itki mekanik enerjiyi artırıp aracı daha yüksek ve periyodu daha uzun bir eliptik yörüngeye yükseltir; bu yüzden açısal olarak geride kalır.'),
  ('Aynı maddeden yapılmış iki homojen küresel gezegenden X gezegeninin yarıçapı R, Y gezegeninin yarıçapı 3R\'dir. X gezegeninin yüzeyindeki çekim ivmesi g_X, Y\'nin yüzeyindeki çekim ivmesi g_Y ise g_X / g_Y oranı kaçtır?', '1/3', ['1/9', '3', '9'], 'Sabit yoğunlukta g = (4/3)πGρR ile yarıçapla doğru orantılı olduğundan g_X / g_Y = R/(3R) = 1/3 bulunur.'),
];
